// --- refusals --------------------------------------------------------------

/// Which part of a document a refusal is about.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Entity {
    /// The document itself.
    Document,
    /// The `player` field bag.
    Player,
    /// One monster, by roster position.
    Monster(usize),
    /// One card, by physical uid.
    Card(u32),
    /// One continuation frame, by stack position.
    Frame(usize),
}

impl fmt::Display for Entity {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Entity::Document => f.write_str("document"),
            Entity::Player => f.write_str("player"),
            Entity::Monster(index) => write!(f, "monsters[{index}]"),
            Entity::Card(uid) => write!(f, "card#{uid}"),
            Entity::Frame(index) => write!(f, "continuations[{index}]"),
        }
    }
}

/// Why a canonical document could not be represented hot.
///
/// Every variant names a concrete missing mechanic or a concrete contract
/// violation. There is no catch-all, and no variant means "close enough".
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum BoundaryRefusal {
    /// The document's `schema` is not the admitted one.
    UnsupportedSchema(String),
    /// The document's `game_build` is outside the admitted set.
    UnsupportedGameBuild(String),
    /// The document carries a refusal instead of a state.
    DocumentCarriesRefusal,
    /// A field the hot representation does not model yet.
    UnsupportedField { entity: Entity, field: String },
    /// A modeled field whose value shape or range is not representable.
    UnrepresentableValue {
        entity: Entity,
        field: String,
        detail: String,
    },
    /// A field present at its dataclass default, which zero-default elision
    /// forbids: a present key means "not at its default".
    NonCanonicalDefault { entity: Entity, field: String },
    /// A field with no dataclass default, and therefore always projected,
    /// that the document does not carry. Filling it in with a guess is how a
    /// round trip stops being one.
    MissingRequiredField { entity: Entity, field: String },
    /// A `piles` key that is not one of the five `State` pile fields.
    UnknownPile(String),
    /// An `rng` key that is not one of the nine named streams.
    UnknownRngStream(String),
    /// A card without physical identity; the hot piles are uid-keyed.
    CardWithoutUid { pile: PileId, index: usize },
    /// A card id outside the generated content registry.
    UnknownCardId(String),
    /// A continuation frame whose variant is declared but not yet inhabited,
    /// or whose class name is unknown.
    UnsupportedFrame(String),
    /// An inhabited frame whose field bag does not match its Python class.
    MalformedFrame { frame_type: String, detail: String },
    /// The catalog could not intern a card.
    Catalog(CatalogError),
    /// The per-combat hook tables could not be built from the entry's relics.
    HookTable(crate::hooks::HookRefusal),
    /// A hot pending selection carried reserved routing bits or an ordinal
    /// outside the closed pile/kind vocabularies.
    PendingSelectionRouting(u8),
}

impl fmt::Display for BoundaryRefusal {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::UnsupportedSchema(schema) => {
                write!(f, "unsupported canonical schema {schema:?}")
            }
            Self::UnsupportedGameBuild(build) => {
                write!(f, "unadmitted game build {build:?}")
            }
            Self::DocumentCarriesRefusal => f.write_str("document carries a refusal, not a state"),
            Self::UnsupportedField { entity, field } => {
                write!(f, "{entity}: unmodeled field {field:?}")
            }
            Self::UnrepresentableValue {
                entity,
                field,
                detail,
            } => write!(f, "{entity}: field {field:?} is unrepresentable: {detail}"),
            Self::NonCanonicalDefault { entity, field } => write!(
                f,
                "{entity}: field {field:?} is present at its dataclass default"
            ),
            Self::MissingRequiredField { entity, field } => write!(
                f,
                "{entity}: undefaulted field {field:?} is absent from the document"
            ),
            Self::UnknownPile(name) => write!(f, "unknown pile {name:?}"),
            Self::UnknownRngStream(name) => write!(f, "unknown rng stream {name:?}"),
            Self::CardWithoutUid { pile, index } => write!(
                f,
                "pile {:?} entry {index} has no physical uid",
                pile.as_str()
            ),
            Self::UnknownCardId(id) => write!(f, "unknown card id {id:?}"),
            Self::UnsupportedFrame(frame_type) => {
                write!(f, "unmodeled continuation frame {frame_type:?}")
            }
            Self::MalformedFrame { frame_type, detail } => {
                write!(f, "malformed {frame_type} frame: {detail}")
            }
            Self::Catalog(error) => write!(f, "catalog: {error:?}"),
            Self::HookTable(refusal) => write!(f, "hook table: {refusal}"),
            Self::PendingSelectionRouting(raw) => {
                write!(f, "pending selection routing byte {raw:#04x} is invalid")
            }
        }
    }
}

impl std::error::Error for BoundaryRefusal {}

impl From<CatalogError> for BoundaryRefusal {
    fn from(error: CatalogError) -> Self {
        Self::Catalog(error)
    }
}

impl From<crate::hot::PendingSelectionRoutingError> for BoundaryRefusal {
    fn from(error: crate::hot::PendingSelectionRoutingError) -> Self {
        Self::PendingSelectionRouting(error.raw())
    }
}

// --- the field tables ------------------------------------------------------

/// A mapped field's `combat_sim` dataclass default, which is exactly what
/// zero-default elision means: an absent key is this value.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FieldDefault {
    /// The dataclass field has no default; the key is always present.
    Required,
    /// Default is this integer.
    Int(i64),
    /// Default is this boolean.
    Bool(bool),
    /// Default is this text.
    Text(&'static str),
    /// Default is the empty tuple, which projects as `[]`.
    EmptyList,
    /// Default is `None`.
    Null,
}

impl FieldDefault {
    /// Whether `value` is this field's default, with Python's type identity
    /// rule: `0` and `false` are distinct, so an integer default matches only
    /// a JSON number (`as_i64` yields `None` for a boolean or a null) and a
    /// boolean default matches only a JSON boolean.
    fn matches(self, value: &Value) -> bool {
        match self {
            Self::Required => false,
            Self::Int(number) => value.as_i64() == Some(number),
            Self::Bool(flag) => value.as_bool() == Some(flag),
            Self::Text(text) => value.as_str() == Some(text),
            Self::EmptyList => value.as_array().is_some_and(|items| items.is_empty()),
            Self::Null => value.is_null(),
        }
    }
}

