/// One mapped field: canonical name, hot slot, dataclass default.
#[derive(Clone, Copy, Debug)]
pub struct FieldSpec<S: 'static> {
    /// The canonical field name.
    pub name: &'static str,
    /// Where it lives in the hot representation.
    pub slot: S,
    /// Its `combat_sim` dataclass default.
    pub default: FieldDefault,
}

/// Mapped `State` fields, ascending by name.
///
/// Defaults are read from `combat_sim.State`'s dataclass declaration.
// `ascension`'s wire default below is `encounters::MODELED_ASCENSION`, spelled
// as a literal because `tools/projection_parity_census.py` read the table
// (deleted #2999; `PROJECTION_PARITY_CENSUS.md` is its frozen last run).
const _: () = assert!(crate::encounters::MODELED_ASCENSION == 10);

