fn deep_relic_ownership_matches(state: &HotState, catalog: &Catalog) -> bool {
    let owns = |relic| catalog.hooks().owns(relic);
    state.hand_drill_owned() == owns(RelicId::RelicHandDrill)
        && state.snecko_skull_owned() == owns(RelicId::RelicSneckoSkull)
        && state.the_boot_owned() == owns(RelicId::RelicTheBoot)
        && state.tungsten_rod_owned() == owns(RelicId::RelicTungstenRod)
        && state.paper_krane_owned() == owns(RelicId::RelicPaperKrane)
        && state.philosophers_stone_owned() == owns(RelicId::RelicPhilosophersStone)
        && state.fanouts.beating_remnant_owned() == owns(RelicId::RelicBeatingRemnant)
        && state.fanouts.brilliant_scarf_owned() == owns(RelicId::RelicBrilliantScarf)
        && state.fanouts.ectoplasm_owned() == owns(RelicId::RelicEctoplasm)
        && state.fanouts.lizard_tail_owned() == owns(RelicId::RelicLizardTail)
        && state.fanouts.ruined_helmet_owned() == owns(RelicId::RelicRuinedHelmet)
        && state.fanouts.undying_sigil_owned() == owns(RelicId::RelicUndyingSigil)
}

pub(crate) fn batch_eight_relic_state_is_exact(state: &HotState, catalog: &Catalog) -> bool {
    let owns = |relic| catalog.hooks().owns(relic);
    (owns(RelicId::RelicBeatingRemnant) || state.fanouts.beating_remnant_damage_received() == 0)
        && (owns(RelicId::RelicBoneTea) || state.fanouts.bone_tea_combats_left() == 0)
        && (owns(RelicId::RelicBurningSticks) || !state.fanouts.burning_sticks_used())
        && (owns(RelicId::RelicGalacticDust) || state.fanouts.galactic_dust() == 0)
        && (owns(RelicId::RelicIronClub) || state.fanouts.iron_club_cards() == 0)
        && (owns(RelicId::RelicKusarigama) || state.fanouts.kusarigama() == 0)
        && (owns(RelicId::RelicLizardTail) || !state.fanouts.lizard_tail_used())
        && (owns(RelicId::RelicMiniRegent) || !state.fanouts.mini_regent_used())
        && (owns(RelicId::RelicPenNib) || state.fanouts.pen_nib() == 0)
        && (owns(RelicId::RelicRuinedHelmet) || !state.fanouts.ruined_helmet_used())
        // The potion subsystem predates relic-inventory projection and keeps
        // accepting a standalone Sozu veto carrier. Newly owned Sozu must,
        // however, always hydrate that carrier.
        && (!owns(RelicId::RelicSozu) || state.fanouts.potion_sozu())
        && (owns(RelicId::RelicThrowingAxe) || !state.fanouts.throwing_axe_available())
        && (owns(RelicId::RelicTuningFork) || state.fanouts.tuning_fork_skills() == 0)
        && (owns(RelicId::RelicVambrace)
            || !state.fanouts.vambrace_available()
                && state.fanouts.vambrace_trigger_uid().is_none())
        && state
            .fanouts
            .vambrace_trigger_uid()
            .is_none_or(|uid| owns(RelicId::RelicVambrace) && uid < state.next_card_uid)
}

pub(crate) fn batch_nine_relic_state_is_exact(state: &HotState, catalog: &Catalog) -> bool {
    let owns = |relic| catalog.hooks().owns(relic);
    let history_entries_are_exact = [
        state.fanouts.history_course_attack_current_turn(),
        state.fanouts.history_course_attack_previous_turn(),
    ]
    .into_iter()
    .flatten()
    .all(|entry| {
        entry.card.uid < state.next_card_uid
            && entry.card.flags & crate::hot::CARD_FLAG_DUPE == 0
            && catalog
                .spec(entry.card.atom)
                .is_some_and(|spec| spec.is_attack)
            && PileId::ALL
                .into_iter()
                .flat_map(|pile| state.piles.get(pile).as_slice())
                .filter(|card| card.uid == entry.card.uid)
                .count()
                <= 1
    });
    (owns(RelicId::RelicHistoryCourse)
        || state.fanouts.history_course_attack_current_turn().is_none()
            && state
                .fanouts
                .history_course_attack_previous_turn()
                .is_none())
        && history_entries_are_exact
        && (owns(RelicId::RelicCentennialPuzzle) || !state.fanouts.puzzle_armed())
        && (owns(RelicId::RelicMusicBox)
            || !state.fanouts.music_box_used_this_turn()
                && state.fanouts.music_box_card_uid().is_none())
        && state
            .fanouts
            .music_box_card_uid()
            .is_none_or(|uid| owns(RelicId::RelicMusicBox) && uid < state.next_card_uid)
        && (owns(RelicId::RelicJossPaper) == (state.fanouts.joss_paper_cards_exhausted() >= 0))
        && (owns(RelicId::RelicJossPaper) || state.fanouts.joss_paper_ethereal_count() == 0)
        && (owns(RelicId::RelicPumpkinCandle) == (state.fanouts.pumpkin_candle_kindle_count() >= 0))
        && (owns(RelicId::RelicPaelsLegion) == (state.fanouts.paels_legion_cooldown() >= 0))
        && (owns(RelicId::RelicPaelsLegion)
            || state.fanouts.paels_legion_trigger_uid().is_none()
                && !state.fanouts.paels_legion_triggered_last_turn())
        && state
            .fanouts
            .paels_legion_trigger_uid()
            .is_none_or(|uid| owns(RelicId::RelicPaelsLegion) && uid < state.next_card_uid)
        && (!state.fanouts.paels_legion_triggered_last_turn()
            || state.fanouts.paels_legion_cooldown() > 0)
        && (state.fanouts.paels_legion_cooldown() <= 0
            || state.fanouts.paels_legion_trigger_uid().is_none())
        && (owns(RelicId::RelicPaelsEye) || !state.fanouts.paels_eye_used())
        // Pael's Eye is the only represented extra-turn source, and it marks
        // itself used as the extra turn begins (#3049).
        && (!state.fanouts.players_taking_extra_turn() || state.fanouts.paels_eye_used())
        && (owns(RelicId::RelicRegalite) || !state.fanouts.regalite_used_this_turn())
        && state.fanouts.self_forming_clay_owned() == owns(RelicId::RelicSelfFormingClay)
        && state.fanouts.gremlin_horn_owned() == owns(RelicId::RelicGremlinHorn)
        && state.fanouts.red_skull_owned() == owns(RelicId::RelicRedSkull)
        && !state.fanouts.red_skull_latch_stale()
        && matches!(state.regalite_block_amount, 4 | 6)
}

fn canonical_default(value: &Value) -> bool {
    matches!(value, Value::Bool(false)) || value.as_i64() == Some(0)
}

/// Decode the potion belt as one atomic cross-field record. The sparse slots
/// are authoritative; the dense `potions` list is only an exact ordered
/// non-null mirror and can never synthesize missing topology.
fn hydrate_potion_belt(
    document: &CanonicalStateV2,
    state: &mut HotState,
    catalog: &Catalog,
) -> Result<(), BoundaryRefusal> {
    let entity = Entity::Player;
    let slots_value = document.player.get("potion_slots");
    let dense_value = document.player.get("potions");
    let inert_value = document.player.get("inert_potions");
    let mut slots = Vec::new();
    if let Some(value) = slots_value {
        let rows = value
            .as_array()
            .ok_or_else(|| unrepresentable(entity, "potion_slots", "expected a nullable list"))?;
        if rows.is_empty() || rows.len() > usize::from(u8::MAX) + 1 {
            return Err(unrepresentable(
                entity,
                "potion_slots",
                "capacity must be in 1..=256",
            ));
        }
        slots.reserve(rows.len());
        for row in rows {
            if row.is_null() {
                slots.push(None);
                continue;
            }
            let name = row.as_str().ok_or_else(|| {
                unrepresentable(entity, "potion_slots", "slots must be potion names or null")
            })?;
            let potion = PotionId::from_str(name).ok_or_else(|| {
                unrepresentable(
                    entity,
                    "potion_slots",
                    "unknown/inert potion identity is not represented",
                )
            })?;
            slots.push(Some(potion));
        }
    }

    let dense = match dense_value {
        None => Vec::new(),
        Some(value) => value
            .as_array()
            .ok_or_else(|| unrepresentable(entity, "potions", "expected an ordered list"))?
            .iter()
            .map(|row| {
                row.as_str().and_then(PotionId::from_str).ok_or_else(|| {
                    unrepresentable(
                        entity,
                        "potions",
                        "dense mirror contains an unknown potion identity",
                    )
                })
            })
            .collect::<Result<Vec<_>, _>>()?,
    };
    let expected_dense = slots.iter().copied().flatten().collect::<Vec<_>>();
    if dense != expected_dense {
        return Err(unrepresentable(
            entity,
            "potions",
            "dense mirror must equal the sparse slots' ordered non-null identities",
        ));
    }
    if let Some(value) = inert_value {
        let inert = value
            .as_array()
            .ok_or_else(|| unrepresentable(entity, "inert_potions", "expected an ordered list"))?;
        if !inert.is_empty() {
            return Err(unrepresentable(
                entity,
                "inert_potions",
                "Part A refuses every unknown/inert potion identity",
            ));
        }
    }

    let flag = |name: &'static str| -> Result<bool, BoundaryRefusal> {
        document
            .player
            .get(name)
            .map_or(Ok(false), |value| as_flag(entity, name, value))
    };
    let fully_unlocked_pool = flag("fully_unlocked_potion_pool")?;
    // #3347: the pool proof a materialised belt carries is generation
    // provenance only (IL and the caller census:
    // `engine::potions::potion_belt_state_is_exact`). The belt's contents
    // are checked above by identity. So a belt needs either proof that
    // `engine::potions::generation_potion_profile` accepts: the solo-Ironclad
    // flag, or a recorded unlock profile, which decides every owner's pool
    // (`GetPotionOptions` `0x112fba` reads the owner's own fourth epoch and
    // `POTION1/2`, never `IRONCLAD4` for another owner). A belt with neither
    // still refuses here.
    if !slots.is_empty() && !fully_unlocked_pool && !document_records_unlock_profile(document) {
        return Err(unrepresentable(
            entity,
            "fully_unlocked_potion_pool",
            "exact current-build potion-pool provenance is required",
        ));
    }
    let sozu = flag("sozu")?;
    if slots.is_empty() && sozu && !catalog.hooks().owns(RelicId::RelicSozu) {
        return Err(unrepresentable(
            entity,
            "potion_slots",
            "an empty Sozu carrier requires relic inventory",
        ));
    }
    if !state.fanouts.set_potion_belt(
        slots,
        sozu,
        flag("belt_buckle")?,
        flag("belt_buckle_applied")?,
        flag("strict_potions")?,
        fully_unlocked_pool,
    ) {
        return Err(unrepresentable(
            entity,
            "potion_slots",
            "belt capacity, flags, or Belt Buckle latch are incoherent",
        ));
    }
    Ok(())
}

fn generation_pool_from_wire(value: &str) -> Option<RewardPool> {
    match value {
        "defect" => Some(RewardPool::Defect),
        "ironclad" => Some(RewardPool::Ironclad),
        "necrobinder" => Some(RewardPool::Necrobinder),
        "regent" => Some(RewardPool::Regent),
        "silent" => Some(RewardPool::Silent),
        _ => None,
    }
}

fn generation_pool_wire(pool: RewardPool) -> &'static str {
    match pool {
        RewardPool::Defect => "defect",
        RewardPool::Ironclad => "ironclad",
        RewardPool::Necrobinder => "necrobinder",
        RewardPool::Regent => "regent",
        RewardPool::Silent => "silent",
    }
}

