    #[test]
    fn after_side_turn_start_order_round_trips_all_342_ordered_pairs() {
        let mut canonical_bytes = Vec::new();
        for first_token in crate::hot::AfterSideTurnStartToken::ALL {
            for second_token in crate::hot::AfterSideTurnStartToken::ALL {
                if first_token == second_token {
                    continue;
                }
                let first = first_token.as_str();
                let second = second_token.as_str();
                let mut document = fixture();
                document.player.insert(first.to_owned(), json!(1));
                document.player.insert(second.to_owned(), json!(1));
                document.player.insert(
                    "after_side_turn_start_power_order".to_owned(),
                    json!([first, second]),
                );
                if matches!(
                    (first_token, second_token),
                    (crate::hot::AfterSideTurnStartToken::Furnace, _)
                        | (_, crate::hot::AfterSideTurnStartToken::Furnace)
                ) {
                    document
                        .player
                        .insert("exact_piles".to_owned(), json!(true));
                }
                let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
                let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
                assert_eq!(
                    HotBoundary::try_to_canonical(&state, &catalog).unwrap(),
                    document,
                    "{first} then {second}"
                );
                canonical_bytes.push(document.canonical_json());
            }
        }
        canonical_bytes.sort();
        canonical_bytes.dedup();
        assert_eq!(canonical_bytes.len(), 19 * 18);

        for token in crate::hot::AfterSideTurnStartToken::ALL {
            let field = token.as_str();
            let mut document = fixture();
            document.player.insert(field.to_owned(), json!(1));
            if token == crate::hot::AfterSideTurnStartToken::Furnace {
                document
                    .player
                    .insert("exact_piles".to_owned(), json!(true));
            }
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(
                HotBoundary::try_to_canonical(&state, &catalog).unwrap(),
                document
            );
        }
    }

    #[test]
    fn after_side_expiry_and_reacquisition_keep_canonical_structural_equality() {
        let mut document = fixture();
        document.player.insert("clarity".to_owned(), json!(1));
        document.player.insert("blur".to_owned(), json!(1));
        document.player.insert(
            "after_side_turn_start_power_order".to_owned(),
            json!(["clarity", "blur"]),
        );
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();

        assert!(state.fanouts.set_clarity(0));
        state.powers.set(PowerId::Blur, SlotWire::Int, 0);
        state
            .fanouts
            .unregister_after_side_turn_start(PowerId::Blur);
        let empty = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let empty_rebuilt = HotBoundary::from_canonical(&empty, &catalog).unwrap();
        assert_eq!(state, empty_rebuilt, "vacated token tails are canonical");

        assert!(state.fanouts.set_clarity(1));
        let clarity = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let clarity_rebuilt = HotBoundary::from_canonical(&clarity, &catalog).unwrap();
        assert_eq!(state, clarity_rebuilt, "Clarity reacquisition is canonical");

        state.powers.set(PowerId::Blur, SlotWire::Int, 1);
        assert!(state.fanouts.register_after_side_turn_start(PowerId::Blur));
        let both = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let both_rebuilt = HotBoundary::from_canonical(&both, &catalog).unwrap();
        assert_eq!(state, both_rebuilt, "Power reacquisition is canonical");
    }

    #[test]
    fn hit_power_order_round_trips_all_permutations_and_reconstructs_singletons() {
        let permutations = [
            ["flame_barrier", "reflect", "the_gambit"],
            ["flame_barrier", "the_gambit", "reflect"],
            ["reflect", "flame_barrier", "the_gambit"],
            ["reflect", "the_gambit", "flame_barrier"],
            ["the_gambit", "flame_barrier", "reflect"],
            ["the_gambit", "reflect", "flame_barrier"],
        ];
        let mut bytes = Vec::new();
        for order in permutations {
            let mut document = fixture();
            document.player.insert("flame_barrier".to_owned(), json!(4));
            document.player.insert("reflect".to_owned(), json!(2));
            document.player.insert("the_gambit".to_owned(), json!(1));
            document
                .player
                .insert("after_damage_received_power_order".to_owned(), json!(order));
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(
                HotBoundary::try_to_canonical(&state, &catalog).unwrap(),
                document
            );
            bytes.push(document.canonical_json());
        }
        bytes.sort();
        bytes.dedup();
        assert_eq!(bytes.len(), 6);

        for field in ["flame_barrier", "reflect", "the_gambit"] {
            let mut document = fixture();
            document.player.insert(field.to_owned(), json!(1));
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(
                HotBoundary::try_to_canonical(&state, &catalog).unwrap(),
                document
            );
        }
    }

    #[test]
    fn hit_power_order_rejects_missing_duplicate_unknown_omitted_and_extraneous() {
        let refuses = |document: &CanonicalStateV2| {
            let catalog = HotBoundary::catalog_from_canonical(document).unwrap();
            HotBoundary::from_canonical(document, &catalog).is_err()
        };
        let mut exact = fixture();
        exact.player.insert("flame_barrier".to_owned(), json!(4));
        exact.player.insert("reflect".to_owned(), json!(1));
        exact.player.insert(
            "after_damage_received_power_order".to_owned(),
            json!(["reflect", "flame_barrier"]),
        );
        let mut missing = exact.clone();
        missing.player.remove("after_damage_received_power_order");
        assert!(refuses(&missing));
        for order in [
            json!(["reflect", "reflect"]),
            json!(["reflect"]),
            json!(["reflect", "flame_barrier", "the_gambit"]),
            json!(["reflect", "alien"]),
        ] {
            let mut malformed = exact.clone();
            malformed
                .player
                .insert("after_damage_received_power_order".to_owned(), order);
            assert!(refuses(&malformed));
        }
        let mut singleton = fixture();
        singleton.player.insert("reflect".to_owned(), json!(1));
        singleton.player.insert(
            "after_damage_received_power_order".to_owned(),
            json!(["reflect"]),
        );
        assert!(refuses(&singleton));
    }

