    #[test]
    fn batch139_uid_history_rejects_duplicate_unallocated_nonexact_and_orphan_tampering() {
        let cases = [
            ("self_return_finished_uids_current_turn", json!([0, 0])),
            ("self_return_finished_uids_previous_turn", json!([10])),
        ];
        for (field, value) in cases {
            let mut document = batch139_document();
            document.player.insert(field.to_owned(), value);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            assert!(
                HotBoundary::from_canonical(&document, &catalog).is_err(),
                "accepted tampered {field}"
            );
        }

        let mut document = batch139_document();
        document.player.remove("exact_piles");
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        assert!(HotBoundary::from_canonical(&document, &catalog).is_err());

        // This Rust slice has no suspendable BeforeHandDraw owner/cursor.
        // Subsets, permutations, omissions, historical additions, and an
        // ordinary-phase orphan are therefore all rejected at the boundary.
        for snapshot in [json!([0]), json!([5, 0]), json!([0, 5]), json!([0, 5, 6])] {
            let mut document = batch139_document();
            document
                .player
                .insert("before_hand_draw_card_listener_uids".to_owned(), snapshot);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            assert!(HotBoundary::from_canonical(&document, &catalog).is_err());
        }
    }

    #[test]
    fn potion_belt_refuses_missing_topology_proof_mirror_inert_and_capacity_drift() {
        let cases = [
            {
                let mut document = potion_document(json!(["FIRE_POTION"]), json!(["FIRE_POTION"]));
                document.player.remove("fully_unlocked_potion_pool");
                document
            },
            potion_document(json!(["FIRE_POTION", null]), json!([])),
            {
                let mut document = fixture();
                document
                    .player
                    .insert("potions".to_owned(), json!(["FIRE_POTION"]));
                document
            },
            potion_document(json!(["UNKNOWN_POTION"]), json!(["UNKNOWN_POTION"])),
            {
                let mut document = potion_document(json!([null]), json!([]));
                document
                    .player
                    .insert("inert_potions".to_owned(), json!(["UNKNOWN_POTION"]));
                document
            },
            potion_document(Value::Array(vec![Value::Null; 257]), json!([])),
            {
                let mut document = fixture();
                document.player.insert("sozu".to_owned(), Value::Bool(true));
                document
            },
        ];
        for document in cases {
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            assert!(HotBoundary::from_canonical(&document, &catalog).is_err());
        }
    }

    /// A recorded profile revealing every epoch except `IRONCLAD4_EPOCH`: the
    /// shape of a non-Ironclad player who never cleared Ironclad's fourth
    /// epoch, which the solo-Ironclad flag cannot prove (#3347).
    fn issue3347_profile_hiding_ironclad4() -> Value {
        Value::Array(
            crate::content_tables::UNLOCK_EPOCH_UNIVERSE_V1101
                .iter()
                .copied()
                .filter(|epoch| *epoch != "IRONCLAD4_EPOCH")
                .map(Value::from)
                .collect(),
        )
    }

    /// #3347: a materialised belt needs a proof of the generation pool, and
    /// either proof `generation_potion_profile` accepts suffices. One branch
    /// per case of the gate in `hydrate_potion_belt`:
    /// * the flag alone admits (unchanged);
    /// * a recorded profile alone admits, for a non-Ironclad owner whose
    ///   profile hides `IRONCLAD4` (new). The flag stays false, the document
    ///   round-trips losslessly, and engine admission accepts the belt;
    /// * neither refuses by the same field and text as before.
    #[test]
    fn issue3347_a_recorded_profile_proves_a_belt_without_the_ironclad_flag() {
        let belt = || potion_document(json!(["FIRE_POTION", null]), json!(["FIRE_POTION"]));

        let flag_only = belt();
        let catalog = HotBoundary::catalog_from_canonical(&flag_only).unwrap();
        let state = HotBoundary::from_canonical(&flag_only, &catalog).unwrap();
        assert!(state.fanouts.fully_unlocked_potion_pool());
        assert!(crate::engine::potions::potion_belt_state_is_exact(
            &state, &catalog
        ));

        let mut profile_only = belt();
        profile_only.player.remove("fully_unlocked_potion_pool");
        profile_only
            .player
            .insert("reward_card_pool".to_owned(), json!("Silent"));
        profile_only.player.insert(
            "splash_unlock_epochs".to_owned(),
            issue3347_profile_hiding_ironclad4(),
        );
        let catalog = HotBoundary::catalog_from_canonical(&profile_only).unwrap();
        let state = HotBoundary::from_canonical(&profile_only, &catalog).unwrap();
        assert_eq!(
            state.fanouts.potion_slots(),
            [Some(PotionId::FirePotion), None]
        );
        assert!(!state.fanouts.fully_unlocked_potion_pool());
        assert!(crate::engine::potions::potion_belt_state_is_exact(
            &state, &catalog
        ));
        assert_eq!(
            HotBoundary::try_to_canonical(&state, &catalog).unwrap(),
            profile_only
        );
        assert_eq!(
            crate::engine::admit(&profile_only, &state, &catalog),
            Ok(())
        );
        // The same hot belt under a catalog that records no profile has no
        // pool proof, and the engine's own belt check says so.
        let bare = HotBoundary::catalog_from_canonical(&fixture()).unwrap();
        assert!(!crate::engine::potions::potion_belt_state_is_exact(
            &state, &bare
        ));

        let mut neither = belt();
        neither.player.remove("fully_unlocked_potion_pool");
        let catalog = HotBoundary::catalog_from_canonical(&neither).unwrap();
        let Err(BoundaryRefusal::UnrepresentableValue { field, detail, .. }) =
            HotBoundary::from_canonical(&neither, &catalog)
        else {
            panic!("a belt with neither pool proof must refuse");
        };
        assert_eq!(field, "fully_unlocked_potion_pool");
        assert_eq!(
            detail,
            "exact current-build potion-pool provenance is required"
        );
    }

    /// #3347: the boundary's Alchemize procurement reachability accepts the
    /// same two proofs as the belt gate. A Necrobinder owner with a recorded
    /// profile, no flag, an empty slot and Alchemize in hand can procure Pot
    /// of Ghouls, so its Soul must be interned; reading the flag alone would
    /// have left the closure empty for a belt the boundary now materialises.
    /// The control without either proof interns no Soul.
    #[test]
    fn issue3347_alchemize_procurement_closure_reads_the_recorded_profile() {
        let soul = CardIdentity {
            id: CardId::Soul,
            upgrade: 0,
            enchantment: None,
        };
        let document = |profile: bool| {
            let mut document = potion_document(json!([null]), json!([]));
            document.player.remove("fully_unlocked_potion_pool");
            document.piles.get_mut("hand").unwrap()[0] = card("ALCHEMIZE", 0);
            document
                .player
                .insert("reward_card_pool".to_owned(), json!("Necrobinder"));
            if profile {
                document.player.insert(
                    "splash_unlock_epochs".to_owned(),
                    issue3347_profile_hiding_ironclad4(),
                );
            }
            document
        };
        let with_profile = HotBoundary::catalog_from_canonical(&document(true)).unwrap();
        assert!(with_profile.atom(&soul).is_some());
        let without = HotBoundary::catalog_from_canonical(&document(false)).unwrap();
        assert!(without.atom(&soul).is_none());
    }

