    #[test]
    fn potion_created_power_state_round_trips_and_bound_attack_refuses_admission() {
        let mut document = fixture();
        document.player.insert("clarity".to_owned(), json!(6));
        document.player.insert("duplication".to_owned(), json!(2));
        document
            .player
            .insert("gigantification".to_owned(), json!(3));
        document
            .player
            .insert("gigantification_bound".to_owned(), json!(true));
        document.player.insert("player_ritual".to_owned(), json!(4));
        document.player.insert("radiance".to_owned(), json!(5));
        document
            .player
            .insert("after_energy_reset_order".to_owned(), json!(["radiance"]));
        append_singleton_side_end_row(&mut document, "duplication");
        append_singleton_side_end_row(&mut document, "ritual");
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);
        assert_eq!(state.fanouts.clarity(), 6);
        assert_eq!(state.fanouts.duplication(), 2);
        assert_eq!(state.fanouts.gigantification(), 3);
        assert!(state.fanouts.gigantification_bound());
        assert_eq!(state.fanouts.player_ritual(), 4);
        assert_eq!(state.fanouts.radiance(), 5);
        assert!(
            crate::engine::admit(&document, &state, &catalog)
                .unwrap_err()
                .contains(crate::engine::MissingCapability::ArgumentShape(
                    "Gigantification bound AttackCommand"
                ))
        );

        document.player.remove("gigantification_bound");
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(crate::engine::admit(&document, &state, &catalog), Ok(()));
    }

