    #[test]
    fn frozen_auto_batch_capture_projects_independently_of_current_live_state() {
        fn frame(entry: &CanonicalCardV2, source: &str) -> CanonicalFrameV2 {
            CanonicalFrameV2 {
                frame_type: FrameKind::FrozenAutoBatch.as_str().to_owned(),
                fields: BTreeMap::from([
                    ("tag".to_owned(), json!("auto_batch")),
                    ("entries".to_owned(), json!([entry])),
                    ("cursor".to_owned(), json!(0)),
                    ("force_exhaust".to_owned(), json!(false)),
                    ("source".to_owned(), json!(source)),
                ]),
            }
        }

        let document = fixture();
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        let live = PileId::ALL
            .into_iter()
            .find_map(|pile| state.piles.get(pile).as_slice().first().copied())
            .unwrap();
        let mut captured = HotBoundary::card_to_canonical(&state, &catalog, live);
        captured.local_keywords = vec!["Ethereal".to_owned(), "Retain".to_owned()];
        captured.transient_keywords = vec!["Retain".to_owned()];
        captured.physical_state = Some(json!([
            "PHYSICAL_CARD_STATE",
            [[1, 3, 0, false], [2, -1, 6, true]],
            17,
            false,
            [[0, true, true], [0, true, true]]
        ]));
        let canonical = frame(&captured, "draw-pile flip");

        assert!(frozen_auto_batch_from_canonical(&canonical, &state, &catalog, true).is_err());
        let record = frozen_auto_batch_from_canonical(&canonical, &state, &catalog, false).unwrap();
        assert!(record.entries[0].state.local_ethereal());
        assert!(record.entries[0].state.local_retain);
        let mut projected_state = state.clone();
        let record_index = projected_state
            .frames
            .push_frozen_auto_batch(&record)
            .unwrap();
        let mut rendered = BTreeMap::from([("tag".to_owned(), json!("auto_batch"))]);
        frozen_auto_batch_to_canonical(record_index, &projected_state, &catalog, &mut rendered)
            .unwrap();
        assert_eq!(rendered, canonical.fields);

        let mut missing = state.clone();
        for pile in PileId::ALL {
            missing
                .piles
                .get_mut(pile)
                .make_mut()
                .retain(|card| card.uid != live.uid);
        }
        assert!(frozen_auto_batch_from_canonical(&canonical, &missing, &catalog, true).is_err());
        let missing_draw =
            frozen_auto_batch_from_canonical(&canonical, &missing, &catalog, false).unwrap();
        assert_eq!(missing_draw, record);

        let missing_sly = frame(&captured, "Sly discard");
        assert!(
            frozen_auto_batch_from_canonical(&missing_sly, &missing, &catalog, false).is_ok(),
            "Stage 3A stores Sly's capture too; live-source validation remains a driver proof"
        );

        let exact_live = HotBoundary::card_to_canonical(&state, &catalog, live);
        let originless = frame(&exact_live, "draw-pile flip");
        let originless_record =
            frozen_auto_batch_from_canonical(&originless, &state, &catalog, true).unwrap();
        let mut originless_state = state.clone();
        let originless_index = originless_state
            .frames
            .push_frozen_auto_batch(&originless_record)
            .unwrap();
        let mut originless_rendered = BTreeMap::from([("tag".to_owned(), json!("auto_batch"))]);
        frozen_auto_batch_to_canonical(
            originless_index,
            &originless_state,
            &catalog,
            &mut originless_rendered,
        )
        .unwrap();
        assert_eq!(originless_rendered, originless.fields);

        let mut duplicate = canonical.clone();
        duplicate
            .fields
            .insert("entries".to_owned(), json!([captured.clone(), captured]));
        assert!(frozen_auto_batch_from_canonical(&duplicate, &state, &catalog, false).is_err());

        let mut unallocated = canonical.clone();
        unallocated.fields.get_mut("entries").unwrap()[0]["uid"] = json!(state.next_card_uid);
        assert!(frozen_auto_batch_from_canonical(&unallocated, &state, &catalog, false).is_err());

        let mut defaulted = canonical;
        defaulted.fields.get_mut("entries").unwrap()[0]["pick"] = json!(false);
        assert!(frozen_auto_batch_from_canonical(&defaulted, &state, &catalog, false).is_err());

        let mut genetic_document = genetic_algorithm_document(6, Some(12));
        genetic_document
            .player
            .insert("next_card_uid".to_owned(), json!(91));
        let genetic_catalog = HotBoundary::catalog_from_canonical(&genetic_document).unwrap();
        let genetic_state =
            HotBoundary::from_canonical(&genetic_document, &genetic_catalog).unwrap();
        let genetic_card = *genetic_state
            .piles
            .get(PileId::Hand)
            .as_slice()
            .last()
            .unwrap();
        let genetic_canonical =
            HotBoundary::card_to_canonical(&genetic_state, &genetic_catalog, genetic_card);
        let genetic_frame = frame(&genetic_canonical, "draw-pile flip");
        let genetic_record = frozen_auto_batch_from_canonical(
            &genetic_frame,
            &genetic_state,
            &genetic_catalog,
            true,
        )
        .unwrap();
        let mut genetic_roundtrip = genetic_state.clone();
        let genetic_index = genetic_roundtrip
            .frames
            .push_frozen_auto_batch(&genetic_record)
            .unwrap();
        let mut genetic_fields = BTreeMap::from([("tag".to_owned(), json!("auto_batch"))]);
        frozen_auto_batch_to_canonical(
            genetic_index,
            &genetic_roundtrip,
            &genetic_catalog,
            &mut genetic_fields,
        )
        .unwrap();
        assert_eq!(genetic_fields, genetic_frame.fields);
    }

    fn pending_record(state: &HotState) -> crate::hot::CardPlayView<'_> {
        state
            .pending
            .as_deref()
            .and_then(|pending| pending.record(&state.frames))
            .expect("authenticated pending CardPlay")
    }

    fn update_pending_record(
        state: &mut HotState,
        update: impl FnOnce(&mut crate::hot::CardPlayRecord),
    ) {
        let pending = state.pending.as_deref().expect("pending selection");
        let mut record = state
            .frames
            .card_play(pending.frame_record)
            .expect("pending CardPlay record")
            .to_owned();
        update(&mut record);
        state
            .frames
            .replace_top_card_play(&record)
            .expect("valid replacement CardPlay");
    }

    fn discovery_document(seed: u64, upgrade: u8) -> CanonicalStateV2 {
        let mut document = fixture();
        let source = &mut document.piles.get_mut("hand").unwrap()[0];
        *source = card(CardId::Discovery.as_str(), 991);
        source.upgrade = i64::from(upgrade);
        document
            .player
            .insert("next_card_uid".to_owned(), json!(992));
        document
            .player
            .insert("reward_card_pool".to_owned(), json!("Ironclad"));
        document
            .player
            .insert("entropy_card_pool".to_owned(), json!("ironclad"));
        document.player.insert(
            "splash_unlock_epochs".to_owned(),
            Value::Array(
                FULLY_UNLOCKED_CARD_POOL_EPOCHS
                    .iter()
                    .copied()
                    .map(Value::from)
                    .collect(),
            ),
        );
        let seeded = Xoshiro256StarStar::from_seed(seed);
        document.rng.insert(
            RngStream::Generation.as_str().to_owned(),
            CanonicalRngV2 {
                counter: seeded.counter,
                words: seeded.words,
            },
        );
        document
    }

    fn stoke_document(upgrade: u8) -> CanonicalStateV2 {
        let mut document = discovery_document(1884, upgrade);
        for pile in document.piles.values_mut() {
            pile.clear();
        }
        document
            .piles
            .retain(|pile, _| matches!(pile.as_str(), "discard" | "draw" | "hand"));
        let mut source = card(CardId::Stoke.as_str(), 991);
        source.upgrade = i64::from(upgrade);
        document.piles.get_mut("hand").unwrap().push(source);
        document
    }

    #[test]
    fn stoke_catalog_preview_is_the_exact_source_level_recursive_fixed_point() {
        for (upgrade, expected_count) in [(0, 158), (1, 112)] {
            let document = stoke_document(upgrade);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let mut levels = [false; 2];
            levels[usize::from(upgrade)] = true;
            let expected = stoke_generation_closure(levels);
            let reachable = catalog
                .reachable_specs()
                .map(|spec| spec.identity)
                .collect::<std::collections::BTreeSet<_>>();
            assert_eq!(expected.len(), expected_count);
            assert_eq!(reachable, expected, "source level {upgrade}");
            assert_eq!(catalog.specs().count(), expected_count);
        }
        let mut both = stoke_document(0);
        let mut upgraded = card(CardId::Stoke.as_str(), 992);
        upgraded.upgrade = 1;
        both.piles.get_mut("draw").unwrap().push(upgraded);
        let catalog = HotBoundary::catalog_from_canonical(&both).unwrap();
        let expected = stoke_generation_closure([true, true]);
        assert_eq!(expected.len(), 158);
        assert_eq!(
            catalog
                .reachable_specs()
                .map(|spec| spec.identity)
                .collect::<std::collections::BTreeSet<_>>(),
            expected
        );
        assert_eq!(catalog.specs().count(), 158);

        for owner in RewardPool::ALL {
            for upgrade in [0, 1] {
                let mut document = stoke_document(upgrade);
                document
                    .player
                    .insert("reward_card_pool".to_owned(), Value::from(owner.as_str()));
                document.player.insert(
                    "entropy_card_pool".to_owned(),
                    Value::from(generation_pool_wire(owner)),
                );
                let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
                let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
                let mut levels = [false; 2];
                levels[usize::from(upgrade)] = true;
                // The SEEDED probe, because the claim is that the preview
                // equals THIS fight's real closure. These documents publish no
                // `spectrum_shift_generation_pool`, so on a Regent owner the
                // real catalog gates Entropy off; an unseeded probe would
                // expand the five-class union the catalog deliberately did not
                // intern and this comparison would fail on the probe's own
                // over-closure rather than on anything the boundary did.
                let expected = stoke_generation_closure_seeded(levels, owner, Some(&catalog));
                assert_eq!(
                    catalog
                        .reachable_specs()
                        .map(|spec| spec.identity)
                        .collect::<std::collections::BTreeSet<_>>(),
                    expected,
                    "Stoke{upgrade}+ closure for {owner:?}",
                );
                assert!(
                    !crate::engine::admit(&document, &state, &catalog)
                        .err()
                        .is_some_and(|refusal| refusal.contains(
                            crate::engine::MissingCapability::ArgumentShape(
                                "Stoke generation provenance"
                            )
                        )),
                    "owner {owner:?} Stoke{upgrade}+ has a complete provenance witness",
                );
            }
        }
    }

    fn first_admitted_discovery_document() -> CanonicalStateV2 {
        (0..4096)
            .map(|seed| discovery_document(seed, 0))
            .find(|document| {
                let Ok(catalog) = HotBoundary::catalog_from_canonical(document) else {
                    return false;
                };
                let Ok(state) = HotBoundary::from_canonical(document, &catalog) else {
                    return false;
                };
                crate::engine::admit(document, &state, &catalog).is_ok()
            })
            .expect("one exact Discovery prefix must be fully implemented")
    }

    fn genetic_algorithm_document(growth: i64, deck_row: Option<u32>) -> CanonicalStateV2 {
        let mut document = fixture();
        let mut genetic = card(CardId::GeneticAlgorithm.as_str(), 90);
        genetic.physical_state = Some(json!(["PHYSICAL_CARD_STATE", [], 0, false, []]));
        genetic.extra = vec![json!(["GENETIC_ALGORITHM_STATE", growth, deck_row])];
        document.piles.get_mut("hand").unwrap().push(genetic);
        if let Some(row) = deck_row {
            document.player.insert(
                "genetic_algorithm_deck_growth".to_owned(),
                json!([[row, growth]]),
            );
        }
        document
    }

    #[test]
    fn genetic_algorithm_card_tail_and_master_relation_round_trip_exactly() {
        let linked = genetic_algorithm_document(6, Some(12));
        let catalog = HotBoundary::catalog_from_canonical(&linked).unwrap();
        let state = HotBoundary::from_canonical(&linked, &catalog).unwrap();
        let card = state.piles.get(PileId::Hand).as_slice().last().unwrap();
        assert_ne!(card.flags & CARD_FLAG_GENETIC_ALGORITHM_STATE, 0);
        let instance = state.card_states.get(card.uid).genetic_algorithm;
        assert_eq!(instance.growth(), 6);
        assert_eq!(instance.deck_row(), Some(12));
        assert_eq!(
            crate::engine::admission::admit(&linked, &state, &catalog),
            Ok(())
        );
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), linked);

        let detached_zero = genetic_algorithm_document(0, None);
        assert_eq!(round_trip(&detached_zero), detached_zero);
    }

    #[test]
    fn genetic_algorithm_boundary_refuses_broken_identity_and_master_relations() {
        let mut mismatch = genetic_algorithm_document(6, Some(12));
        mismatch
            .player
            .insert("genetic_algorithm_deck_growth".to_owned(), json!([[12, 5]]));
        assert!(matches!(
            refuse(&mismatch),
            BoundaryRefusal::UnrepresentableValue {
                entity: Entity::Player,
                ref field,
                ..
            } if matches!(field.as_str(), "genetic_algorithm_deck_growth")
        ));

        let mut duplicate = genetic_algorithm_document(6, Some(12));
        let mut second = card(CardId::GeneticAlgorithm.as_str(), 91);
        second.physical_state = Some(json!(["PHYSICAL_CARD_STATE", [], 0, false, []]));
        second.extra = vec![json!(["GENETIC_ALGORITHM_STATE", 8, 12])];
        duplicate.piles.get_mut("draw").unwrap().push(second);
        duplicate.player.insert(
            "genetic_algorithm_deck_growth".to_owned(),
            json!([[12, 6], [12, 8]]),
        );
        assert!(matches!(
            refuse(&duplicate),
            BoundaryRefusal::UnrepresentableValue {
                entity: Entity::Player,
                ref field,
                ..
            } if matches!(field.as_str(), "genetic_algorithm_deck_growth")
        ));

        let mut wrong_owner = fixture();
        let hand_card = wrong_owner
            .piles
            .get_mut("hand")
            .unwrap()
            .first_mut()
            .unwrap();
        hand_card.extra = vec![json!(["GENETIC_ALGORITHM_STATE", 1, null])];
        wrong_owner
            .player
            .insert("exact_piles".to_owned(), json!(true));
        assert!(matches!(
            refuse(&wrong_owner),
            BoundaryRefusal::UnrepresentableValue {
                entity: Entity::Card(_),
                ref field,
                ..
            } if matches!(field.as_str(), "extra")
        ));
    }

