    #[test]
    fn the_fixture_round_trips_byte_for_byte() {
        let document = fixture();
        let back = round_trip(&document);
        assert_eq!(back.canonical_json(), FIXTURE.trim_end());
        assert_eq!(back.differential_digest(), document.differential_digest());
        assert_eq!(back, document);
    }

    #[test]
    fn constrict_active_and_inactive_sources_round_trip_and_admit_exactly() {
        let document = constrict_document();
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(state.fanouts.constrict_amount(), 3);
        assert_eq!(catalog.moves(MonsterKind::SlitheringStrangler).len(), 3);
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);

        assert_eq!(
            crate::engine::admission::admit(&document, &state, &catalog),
            Ok(())
        );

        let mut inactive = document.clone();
        inactive.player.remove("constrict_sources");
        remove_singleton_side_end_row(&mut inactive, "constrict");
        let inactive_catalog = HotBoundary::catalog_from_canonical(&inactive).unwrap();
        assert_eq!(
            inactive_catalog
                .moves(MonsterKind::SlitheringStrangler)
                .len(),
            3
        );
        let inactive_state = HotBoundary::from_canonical(&inactive, &inactive_catalog).unwrap();
        assert_eq!(inactive_state.fanouts.constrict_amount(), 0);
        assert_eq!(
            HotBoundary::to_canonical(&inactive_state, &inactive_catalog),
            inactive
        );
        assert_eq!(
            crate::engine::admission::admit(&inactive, &inactive_state, &inactive_catalog),
            Ok(())
        );
    }

    #[test]
    fn absent_constrict_refuses_attack_history_without_the_retained_applier() {
        for (next, log) in [
            ("THWACK_MOVE", json!(["CONSTRICT_MOVE", "THWACK_MOVE"])),
            ("LASH_MOVE", json!(["CONSTRICT_MOVE", "LASH_MOVE"])),
        ] {
            let mut forged = constrict_document();
            forged.player.remove("constrict_sources");
            remove_singleton_side_end_row(&mut forged, "constrict");
            forged.monsters[0].insert("next_move".to_owned(), json!(next));
            forged.monsters[0].insert("move_log".to_owned(), log);
            let catalog = HotBoundary::catalog_from_canonical(&forged).unwrap();
            let state = HotBoundary::from_canonical(&forged, &catalog).unwrap();
            let refusal = crate::engine::admission::admit(&forged, &state, &catalog)
                .expect_err("attack history without Constrict must refuse");
            assert!(
                refusal.contains(crate::engine::admission::MissingCapability::ArgumentShape(
                    "Constrict prospective owner/state"
                ))
            );
        }
    }

