    #[test]
    fn furnace_composes_with_five_certified_disjoint_hook_owners() {
        fn add_furnace(mut document: CanonicalStateV2) -> CanonicalStateV2 {
            document.player.insert(
                "player_phase".to_owned(),
                json!(crate::engine::admission::PHASE_ORDINARY_ACTIONS),
            );
            document
                .player
                .insert("exact_piles".to_owned(), json!(true));
            document
                .player
                .insert("next_card_uid".to_owned(), json!(92));
            document
                .piles
                .get_mut("hand")
                .unwrap()
                .push(card(CardId::Furnace.as_str(), 91));
            document
        }

        let mut monologue = add_furnace(minimal());
        monologue.player.insert("monologue".to_owned(), json!(2));
        monologue.player.insert(
            "monologue_instances".to_owned(),
            json!([[0, 1, 1, 3], [1, 1, 1, 0]]),
        );
        monologue
            .player
            .insert("next_after_side_turn_end_power_uid".to_owned(), json!(2));
        monologue.player.insert(
            "after_side_turn_end_power_order".to_owned(),
            json!([["monologue", 0], ["monologue", 1]]),
        );
        monologue.player.insert(
            "after_card_played_power_order".to_owned(),
            json!([["monologue", 0], ["monologue", 1]]),
        );
        monologue
            .player
            .insert("monologue_strength_applied".to_owned(), json!(3));

        let mut void_form = add_furnace(minimal());
        void_form.player.insert("void_form".to_owned(), json!(2));
        void_form
            .player
            .insert("void_form_cards_played_this_turn".to_owned(), json!(3));
        append_singleton_after_card_played_row(&mut void_form, "void_form");

        let mut sentry = add_furnace(minimal());
        sentry.player.insert("sentry_mode".to_owned(), json!(1));
        sentry.player.insert(
            "before_hand_draw_power_order".to_owned(),
            json!(["sentry_mode"]),
        );

        for (name, document) in [
            ("Monologue", monologue),
            ("Void Form", void_form),
            ("Tender", add_furnace(tender_document(3))),
            ("Constrict", add_furnace(constrict_document())),
            ("Sentry Mode", sentry),
        ] {
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert!(
                crate::steps::regent_forge::furnace_public_state_is_exact(&state),
                "Furnace rejected disjoint {name} private state"
            );
            assert_eq!(
                crate::engine::admission::admit(&document, &state, &catalog),
                Ok(()),
                "Furnace and {name} must admit together"
            );
            assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);
        }
    }

    #[test]
    fn tender_hot_forgery_admission_attributes_raw_owner_and_alien_shapes() {
        let document = tender_document(3);
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let exact = HotBoundary::from_canonical(&document, &catalog).unwrap();

        let mut malformed = exact.clone();
        malformed.powers.set(PowerId::Tender, SlotWire::Int, 0);
        malformed.fanouts.forge_tender_state(false, 3);
        let refusal = crate::engine::admission::admit(&document, &malformed, &catalog)
            .expect_err("raw counter/slot disagreement stays named");
        assert!(
            refusal.contains(crate::engine::admission::MissingCapability::ArgumentShape(
                "Tender private state"
            ))
        );

        let mut wrong_owner = exact.clone();
        wrong_owner.monsters_mut()[0].kind = MonsterKind::FrogKnight;
        let refusal = crate::engine::admission::admit(&document, &wrong_owner, &catalog)
            .expect_err("a non-Hunter cannot authenticate the private applier");
        assert!(
            refusal.contains(crate::engine::admission::MissingCapability::ArgumentShape(
                "Tender owner/state"
            ))
        );

        let mut alien = exact;
        let mut peer = HotMonster::new(MonsterKind::FrogKnight, 10);
        peer.max_hp = 10;
        peer.uid = 24;
        peer.powers.set(PowerId::Tender, SlotWire::Int, 1);
        alien.monsters_mut().push(peer);
        let refusal = crate::engine::admission::admit(&document, &alien, &catalog)
            .expect_err("Tender on a monster stays an independently named alien slot");
        assert!(
            refusal.contains(crate::engine::admission::MissingCapability::ArgumentShape(
                "Tender alien owner"
            ))
        );
    }

    #[test]
    fn tender_admits_represented_live_and_future_consuming_shadow_orders() {
        let mut missing_singleton = tender_document(0);
        missing_singleton.player.remove("tender");
        remove_singleton_side_end_row(&mut missing_singleton, "tender");
        let catalog = HotBoundary::catalog_from_canonical(&missing_singleton).unwrap();
        let state = HotBoundary::from_canonical(&missing_singleton, &catalog).unwrap();
        assert!(
            crate::engine::admission::admit(&missing_singleton, &state, &catalog)
                .unwrap_err()
                .contains(crate::engine::admission::MissingCapability::ArgumentShape(
                    "Tender prospective owner/state"
                ))
        );

        let mut active = tender_document(0);
        active
            .player
            .insert("consuming_shadow".to_owned(), json!(1));
        append_singleton_side_end_row(&mut active, "consuming_shadow");
        let catalog = HotBoundary::catalog_from_canonical(&active).unwrap();
        let state = HotBoundary::from_canonical(&active, &catalog).unwrap();
        assert_eq!(
            crate::engine::admission::admit(&active, &state, &catalog),
            Ok(())
        );

        let mut prospective = active;
        prospective.player.remove("tender");
        remove_singleton_side_end_row(&mut prospective, "tender");
        prospective.monsters[0].insert("next_move".to_owned(), json!("TENDERIZING_GOOP_MOVE"));
        prospective.monsters[0].insert("move_log".to_owned(), json!(["TENDERIZING_GOOP_MOVE"]));
        let catalog = HotBoundary::catalog_from_canonical(&prospective).unwrap();
        let state = HotBoundary::from_canonical(&prospective, &catalog).unwrap();
        assert_eq!(
            crate::engine::admission::admit(&prospective, &state, &catalog),
            Ok(())
        );

        prospective.player.remove("consuming_shadow");
        remove_singleton_side_end_row(&mut prospective, "consuming_shadow");
        prospective
            .piles
            .get_mut("hand")
            .unwrap()
            .push(card(CardId::ConsumingShadow.as_str(), 42));
        let catalog = HotBoundary::catalog_from_canonical(&prospective).unwrap();
        let state = HotBoundary::from_canonical(&prospective, &catalog).unwrap();
        assert_eq!(
            crate::engine::admission::admit(&prospective, &state, &catalog),
            Ok(())
        );
    }

    #[test]
