    #[test]
    fn tender_boundary_rejects_malformed_carrier_owner_and_ai_shapes() {
        let exact = tender_document(3);
        let mut cases = Vec::new();

        let mut explicit_zero = exact.clone();
        explicit_zero
            .player
            .insert("tender_cards_played".to_owned(), json!(0));
        cases.push(explicit_zero);
        for tender in [json!(true), json!(0), json!(2), json!(-1)] {
            let mut malformed = exact.clone();
            malformed.player.insert("tender".to_owned(), tender);
            cases.push(malformed);
        }
        let mut negative_count = exact.clone();
        negative_count
            .player
            .insert("tender_cards_played".to_owned(), json!(-1));
        cases.push(negative_count);
        let mut orphan_count = minimal();
        orphan_count
            .player
            .insert("tender_cards_played".to_owned(), json!(1));
        cases.push(orphan_count);

        let mut missing_owner = exact.clone();
        missing_owner.monsters.clear();
        cases.push(missing_owner);
        let mut alien_owner = exact.clone();
        alien_owner.monsters[0].insert("kind".to_owned(), json!("FROG_KNIGHT"));
        alien_owner.monsters[0].remove("next_move");
        alien_owner.monsters[0].remove("move_log");
        cases.push(alien_owner);
        let mut duplicate_owner = exact.clone();
        let mut second = duplicate_owner.monsters[0].clone();
        second.insert("uid".to_owned(), json!(24));
        duplicate_owner.monsters.push(second);
        cases.push(duplicate_owner);
        let mut duplicate_uid = exact.clone();
        duplicate_uid.monsters.push(BTreeMap::from([
            ("kind".to_owned(), json!("FROG_KNIGHT")),
            ("hp".to_owned(), json!(10)),
            ("max_hp".to_owned(), json!(10)),
            ("uid".to_owned(), json!(23)),
        ]));
        cases.push(duplicate_uid);
        let mut wrong_max = exact.clone();
        wrong_max.monsters[0].insert("max_hp".to_owned(), json!(125));
        cases.push(wrong_max);
        let mut active_goop = exact.clone();
        active_goop.monsters[0].insert("next_move".to_owned(), json!("TENDERIZING_GOOP_MOVE"));
        active_goop.monsters[0].insert("move_log".to_owned(), json!(["TENDERIZING_GOOP_MOVE"]));
        cases.push(active_goop);
        // #3026: PUNCTURE is `maxRepeats = 2`, so GOOP, PUNCTURE, PUNCTURE is
        // reachable; only a third consecutive PUNCTURE is not.
        let mut puncture_repeat = exact.clone();
        puncture_repeat.monsters[0].insert("next_move".to_owned(), json!("PUNCTURE_MOVE"));
        puncture_repeat.monsters[0].insert(
            "move_log".to_owned(),
            json!(["PUNCTURE_MOVE", "PUNCTURE_MOVE", "PUNCTURE_MOVE"]),
        );
        cases.push(puncture_repeat);

        for malformed in cases {
            assert!(
                matches!(
                    refuse(&malformed),
                    BoundaryRefusal::NonCanonicalDefault { .. }
                        | BoundaryRefusal::UnrepresentableValue { .. }
                ),
                "malformed Tender state crossed the boundary: {:?}",
                malformed
            );
        }
    }

