    #[test]
    fn constrict_source_boundary_rejects_every_malformed_or_ambiguous_shape() {
        let exact = constrict_document();
        let mut cases = Vec::new();

        let mut empty = exact.clone();
        empty
            .player
            .insert("constrict_sources".to_owned(), json!([]));
        cases.push(empty);
        for value in [
            json!(17),
            json!([[17]]),
            json!([[17, 3, 6]]),
            json!([[17, 3], [17, 6]]),
            json!([[999, 3]]),
            json!([[17, 0]]),
            json!([[17, -3]]),
            json!([[17, 4]]),
            json!([[17, 2_147_483_648_i64]]),
        ] {
            let mut malformed = exact.clone();
            malformed
                .player
                .insert("constrict_sources".to_owned(), value);
            cases.push(malformed);
        }

        let mut dead = exact.clone();
        dead.monsters[0].insert("hp".to_owned(), json!(0));
        cases.push(dead);

        let mut duplicate_uid = exact.clone();
        duplicate_uid.monsters.push(BTreeMap::from([
            ("kind".to_owned(), json!("FROG_KNIGHT")),
            ("hp".to_owned(), json!(10)),
            ("uid".to_owned(), json!(17)),
        ]));
        cases.push(duplicate_uid);

        let mut alien = exact.clone();
        alien.monsters[0] = BTreeMap::from([
            ("kind".to_owned(), json!("FROG_KNIGHT")),
            ("hp".to_owned(), json!(10)),
            ("uid".to_owned(), json!(17)),
        ]);
        cases.push(alien);

        let mut multiple = exact.clone();
        multiple.monsters.push(BTreeMap::from([
            ("kind".to_owned(), json!("SLITHERING_STRANGLER")),
            ("hp".to_owned(), json!(55)),
            ("max_hp".to_owned(), json!(55)),
            ("uid".to_owned(), json!(18)),
            ("next_move".to_owned(), json!("CONSTRICT_MOVE")),
            ("move_log".to_owned(), json!(["CONSTRICT_MOVE"])),
        ]));
        cases.push(multiple);

        for malformed in cases {
            assert!(
                matches!(
                    refuse(&malformed),
                    BoundaryRefusal::NonCanonicalDefault { .. }
                        | BoundaryRefusal::UnrepresentableValue { .. }
                ),
                "malformed row unexpectedly crossed the boundary: {:?}",
                malformed.player.get("constrict_sources")
            );
        }
    }

    #[test]
    fn constrict_active_multi_roster_and_inactive_default_elision_round_trip() {
        let mut active = constrict_document();
        active.monsters.push(BTreeMap::from([
            ("kind".to_owned(), json!("BOWLBUG_ROCK")),
            ("hp".to_owned(), json!(10)),
            ("max_hp".to_owned(), json!(10)),
            ("uid".to_owned(), json!(18)),
        ]));
        assert_eq!(round_trip(&active), active);
        let active_catalog = HotBoundary::catalog_from_canonical(&active).unwrap();
        let active_state = HotBoundary::from_canonical(&active, &active_catalog).unwrap();
        assert_eq!(
            crate::engine::admission::admit(&active, &active_state, &active_catalog),
            Ok(())
        );

        let mut inactive = constrict_document();
        inactive.player.remove("constrict_sources");
        remove_singleton_side_end_row(&mut inactive, "constrict");
        let catalog = HotBoundary::catalog_from_canonical(&inactive).unwrap();
        let state = HotBoundary::from_canonical(&inactive, &catalog).unwrap();
        assert_eq!(state.fanouts.constrict_amount(), 0);
        let projected = HotBoundary::to_canonical(&state, &catalog);
        assert!(!projected.player.contains_key("constrict_sources"));
        assert_eq!(projected, inactive);
        assert_eq!(
            crate::engine::admission::admit(&inactive, &state, &catalog),
            Ok(())
        );

        let mut post_death = inactive;
        post_death.monsters[0].insert("hp".to_owned(), json!(0));
        let catalog = HotBoundary::catalog_from_canonical(&post_death).unwrap();
        let state = HotBoundary::from_canonical(&post_death, &catalog).unwrap();
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), post_death);
        assert_eq!(
            crate::engine::admission::admit(&post_death, &state, &catalog),
            Ok(()),
            "a retained dead exact applier is history, not a prospective owner"
        );

        for duplicate_history in [true, false] {
            let mut document = post_death.clone();
            if duplicate_history {
                let mut duplicate = document.monsters[0].clone();
                duplicate.insert("uid".to_owned(), json!(18));
                document.monsters.push(duplicate);
            } else {
                document.monsters[0].insert("max_hp".to_owned(), json!(99));
            }
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            let refusal = crate::engine::admission::admit(&document, &state, &catalog)
                .expect_err("malformed dead Strangler history must remain refused");
            assert!(
                refusal.contains(crate::engine::admission::MissingCapability::ArgumentShape(
                    "Constrict prospective owner/state"
                )),
                "dead-history shape (duplicate={duplicate_history}) escaped exactness: {refusal:?}"
            );
        }
    }

    #[test]
    fn dead_constrict_history_allows_later_peers_and_survivors_to_progress() {
        for (name, amount, side_end_token) in [
            ("neurosurge", 3, None),
            ("shadow_step", 2, None),
            ("retain_hand", 1, Some("retain_hand")),
            ("temp_focus", 1, Some("temporary_focus")),
        ] {
            let mut document = post_death_constrict_survivor_document();
            document.player.insert(name.to_owned(), json!(amount));
            if let Some(token) = side_end_token {
                append_singleton_side_end_row(&mut document, token);
            }
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);
            assert_eq!(
                crate::engine::admission::admit(&document, &state, &catalog),
                Ok(()),
                "{name} acquired after Constrict removal must admit"
            );

            let turn_before = state.turn;
            let hp_before = state.hp;
            let mut events = Vec::new();
            crate::engine::turn::end_player_turn(&mut state, &catalog, &mut events).unwrap();
            assert_eq!(state.turn, turn_before + 1, "{name} did not progress");
            assert_eq!(
                hp_before - state.hp,
                16,
                "{name} observed stale Constrict damage"
            );
            assert_eq!(state.fanouts.constrict_amount(), 0);
            assert!(!events.iter().any(|event| {
                matches!(
                    event,
                    crate::engine::Event::MonsterMoved {
                        kind: crate::ids::MoveKind::ConstrictPlayer,
                        ..
                    }
                )
            }));
        }

        let mut document = tender_document(0);
        document.player.insert("hp".to_owned(), json!(100));
        document.player.insert("max_hp".to_owned(), json!(100));
        document.monsters.push(BTreeMap::from([
            ("kind".to_owned(), json!("SLITHERING_STRANGLER")),
            ("hp".to_owned(), json!(0)),
            ("max_hp".to_owned(), json!(55)),
            ("uid".to_owned(), json!(17)),
            ("next_move".to_owned(), json!("THWACK_MOVE")),
            (
                "move_log".to_owned(),
                json!(["CONSTRICT_MOVE", "THWACK_MOVE"]),
            ),
        ]));
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);
        assert_eq!(
            crate::engine::admission::admit(&document, &state, &catalog),
            Ok(()),
            "surviving Hunter/Tender is unrelated to removed Constrict order"
        );

        let turn_before = state.turn;
        let hp_before = state.hp;
        let mut events = Vec::new();
        crate::engine::turn::end_player_turn(&mut state, &catalog, &mut events).unwrap();
        assert_eq!(state.turn, turn_before + 1);
        assert_eq!(hp_before - state.hp, 19);
        assert_eq!(state.fanouts.constrict_amount(), 0);
        assert!(!events.iter().any(|event| {
            matches!(
                event,
                crate::engine::Event::MonsterMoved {
                    kind: crate::ids::MoveKind::ConstrictPlayer,
                    ..
                }
            )
        }));
    }

