    #[test]
    fn constrict_and_teammate_callback_coexist_without_aliasing() {
        let mut document = constrict_document();
        add_minimal_multiplayer_party(&mut document);
        document
            .player
            .insert("intercept_covered".to_owned(), json!([1]));
        document
            .player
            .insert("next_card_uid".to_owned(), json!(11));
        document.player.insert(
            "imitation_clone_records".to_owned(),
            json!([[1, 77, 10, ["INFLAME", 0]]]),
        );
        document
            .player
            .insert("teammate_power_card_pending".to_owned(), json!([1, 77]));
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(state.fanouts.constrict_amount(), 3);
        assert_eq!(
            state
                .fanouts
                .teammate_power_pending(state.multiplayer_ally_key),
            Some((1, 77))
        );
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);
        let refusal = crate::engine::admission::admit(&document, &state, &catalog)
            .expect_err("coexisting multiplayer continuations remain publicly refused");
        assert_eq!(
            refusal.missing().collect::<Vec<_>>(),
            [crate::engine::admission::MissingCapability::ContinuationFrame]
        );

        let mut wrong_source_hot = state.clone();
        assert!(
            wrong_source_hot
                .fanouts
                .set_teammate_power_pending(Some((1, 88)))
        );
        assert!(HotBoundary::try_to_canonical(&wrong_source_hot, &catalog).is_err());
        let mut orphan_hot = state.clone();
        orphan_hot.fanouts.imitation_clones_mut().clear();
        assert!(HotBoundary::try_to_canonical(&orphan_hot, &catalog).is_err());

        let mut missing_ally = constrict_document();
        missing_ally
            .player
            .insert("teammate_power_card_pending".to_owned(), json!([1, 77]));
        assert!(matches!(
            refuse(&missing_ally),
            BoundaryRefusal::UnrepresentableValue { .. }
        ));

        let mut wrong_key = document.clone();
        wrong_key
            .player
            .insert("teammate_power_card_pending".to_owned(), json!([0, 77]));
        assert!(matches!(
            refuse(&wrong_key),
            BoundaryRefusal::UnrepresentableValue { .. }
        ));

        let mut orphan = document;
        orphan.player.remove("imitation_clone_records");
        assert!(matches!(
            refuse(&orphan),
            BoundaryRefusal::UnrepresentableValue { .. }
        ));
    }

