    #[test]
    fn scythe_five_field_physical_state_remains_exact_and_seven_fields_link_a_deck_row() {
        let mut exact = fixture();
        let mut scythe = card(CardId::TheScythe.as_str(), 77);
        scythe.physical_state = Some(json!(["PHYSICAL_CARD_STATE", [], 0, false, []]));
        exact.piles.get_mut("hand").unwrap().push(scythe);
        let catalog = HotBoundary::catalog_from_canonical(&exact).unwrap();
        let hot = HotBoundary::from_canonical(&exact, &catalog).unwrap();
        assert_eq!(HotBoundary::to_canonical(&hot, &catalog), exact);

        // #2941: an ordinary fight's seven-field row links the copy to its
        // save-array deck row, which need not be its uid, and the player's
        // `scythe_deck_growth` names that row with the copy's growth.
        let mut linked = exact.clone();
        linked
            .piles
            .get_mut("hand")
            .unwrap()
            .last_mut()
            .unwrap()
            .physical_state = Some(json!(["PHYSICAL_CARD_STATE", [], 3, false, [], 0, 1]));
        linked
            .player
            .insert("scythe_deck_growth".to_owned(), json!([[1, 3]]));
        let catalog = HotBoundary::catalog_from_canonical(&linked).unwrap();
        let hot = HotBoundary::from_canonical(&linked, &catalog).unwrap();
        assert_eq!(hot.card_states.scythe_deck_links(), &[(77, 1)]);
        assert_eq!(HotBoundary::to_canonical(&hot, &catalog), linked);
        // The master growth is read from the linked copy, so a play's live
        // growth is the DeckVersion's too.
        let mut grown = hot.clone();
        grown.card_states.add_damage_growth(77, 5).unwrap();
        let exported = HotBoundary::to_canonical(&grown, &catalog);
        assert_eq!(exported.player["scythe_deck_growth"], json!([[1, 8]]));
        assert_eq!(
            exported.piles["hand"].last().unwrap().physical_state,
            Some(json!(["PHYSICAL_CARD_STATE", [], 8, false, [], 0, 1]))
        );

        // The growth row must be the linked copy's.
        let mut missing_row = linked.clone();
        missing_row.player.remove("scythe_deck_growth");
        let mut wrong_growth = linked.clone();
        wrong_growth
            .player
            .insert("scythe_deck_growth".to_owned(), json!([[1, 4]]));
        for document in [missing_row, wrong_growth] {
            assert!(matches!(
                refuse(&document),
                BoundaryRefusal::UnrepresentableValue { field, .. }
                    if field.as_str().eq("scythe_deck_growth")
            ));
        }

        // Two copies cannot share one DeckVersion row.
        let mut shared = linked.clone();
        let mut twin = card(CardId::TheScythe.as_str(), 78);
        twin.physical_state = Some(json!(["PHYSICAL_CARD_STATE", [], 3, false, [], 0, 1]));
        shared.piles.get_mut("hand").unwrap().push(twin);
        shared.player.insert("next_card_uid".to_owned(), json!(79));
        assert!(matches!(
            refuse(&shared),
            BoundaryRefusal::UnrepresentableValue { field, detail, .. }
                if field.as_str().eq("scythe_deck_growth")
                    && detail.contains("share one DeckVersion row")
        ));

        // A seventh field belongs only to The Scythe.
        let mut foreign = exact;
        let strike = foreign.piles.get_mut("hand").unwrap().first_mut().unwrap();
        strike.physical_state = Some(json!(["PHYSICAL_CARD_STATE", [], 0, false, [], 0, 1]));
        assert!(matches!(
            refuse(&foreign),
            BoundaryRefusal::UnrepresentableValue { field, .. }
                if field.as_str().eq("physical_state")
        ));
    }

    #[test]
    fn sovereign_blade_cannot_forge_a_pending_selection_in_either_boundary_direction() {
        // Sovereign Blade has one non-selecting body step. It cannot inhabit
        // Program, SeekerStrike, or HandCap; Replay is a different no-target
        // selection shape owned by the replaying card, not by the Blade.
        let (pending_state, pending_catalog) = pending_replay_state(PileId::Play, true, false);
        let mut template = HotBoundary::to_canonical(&pending_state, &pending_catalog);
        let active = template
            .piles
            .get_mut("play")
            .unwrap()
            .iter_mut()
            .find(|card| card.uid == Some(1))
            .unwrap();
        active.id = CardId::SovereignBlade.as_str().to_owned();
        active.sovereign_blade = Some(json!(["SOVEREIGN_BLADE", 10, 1]));
        template.player.insert(
            "pending".to_owned(),
            json!([
                "frame_select",
                1,
                ["select", "hand", 1, 1, null, ["move", "discard", "bottom"]]
            ]),
        );
        template.continuations[0]
            .fields
            .insert("remaining_steps".to_owned(), json!([]));
        let frozen = json!([
            pending_state.monsters[0].slot,
            pending_state.monsters[0].uid
        ]);

        for (seeking, target, label) in [
            (false, frozen.clone(), "absent plus frozen target"),
            (true, Value::Null, "positive plus no target"),
            (false, Value::Null, "absent plus no target mismatch"),
            (true, frozen.clone(), "positive plus frozen target mismatch"),
        ] {
            let mut document = template.clone();
            if seeking {
                document.player.insert("seeking_edge".to_owned(), json!(1));
            } else {
                document.player.remove("seeking_edge");
            }
            document.continuations[0]
                .fields
                .insert("target_identity".to_owned(), target.clone());
            document.continuations[0]
                .fields
                .insert("choice".to_owned(), target);
            let unchanged = document.clone();
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            assert!(
                HotBoundary::from_canonical(&document, &catalog).is_err(),
                "{label}"
            );
            assert_eq!(document, unchanged);
        }

        let mut base = fixture();
        for pile in base.piles.values_mut() {
            pile.clear();
        }
        let mut blade = card(CardId::SovereignBlade.as_str(), 1);
        blade.sovereign_blade = Some(json!(["SOVEREIGN_BLADE", 10, 1]));
        base.piles.entry("play".to_owned()).or_default().push(blade);
        let catalog = HotBoundary::catalog_from_canonical(&base).unwrap();
        let mut hot = HotBoundary::from_canonical(&base, &catalog).unwrap();
        let mut record = crate::hot::CardPlayRecord::pending_for_test(1);
        record.spent = 2;
        record.selection_amount = 1;
        let pending = hot.frames.push_pending_for_test(&record);
        hot.pending = Some(std::sync::Arc::new(pending));
        assert!(HotBoundary::try_to_canonical(&hot, &catalog).is_err());
    }

    #[test]
    fn ringing_tail_and_forced_beast_successor_round_trip_exactly() {
        let mut original = fixture();
        original.player.insert("ringing".to_owned(), json!(true));
        append_singleton_side_end_row(&mut original, "ringing");
        original
            .player
            .insert("exact_piles".to_owned(), json!(true));
        for pile in original.piles.values_mut() {
            for card in pile {
                card.physical_state = Some(json!(["PHYSICAL_CARD_STATE", [], 0, false, []]));
                card.extra = vec![json!(["CARD_AFFLICTION", "RINGING", 1])];
            }
        }
        original.monsters.truncate(1);
        let monster = &mut original.monsters[0];
        monster.insert("kind".to_owned(), json!("CEREMONIAL_BEAST"));
        monster.insert("hp".to_owned(), json!(160));
        monster.insert("max_hp".to_owned(), json!(262));
        monster.insert("loop_pos".to_owned(), json!(1));
        monster.insert("override".to_owned(), json!("STUN_MOVE"));
        monster.insert("forced_follow_up".to_owned(), json!("BEAST_CRY_MOVE"));

        let catalog = HotBoundary::catalog_from_canonical(&original).unwrap();
        let hot = HotBoundary::from_canonical(&original, &catalog).unwrap();
        assert!(hot.ringing());
        assert_eq!(hot.monsters[0].override_state, MonsterOverride::BeastStun);
        assert_eq!(hot.monsters[0].forced_follow_up, MonsterFollowUp::BeastCry);
        assert!(crate::boundary::PILE_FIELDS.iter().all(|(pile, _)| {
            hot.piles
                .get(*pile)
                .as_slice()
                .iter()
                .all(|card| card.flags & CARD_FLAG_RINGING != 0)
        }));
        assert_eq!(HotBoundary::to_canonical(&hot, &catalog), original);

        for malformed in [
            json!(["CARD_AFFLICTION", "RINGING", 0]),
            json!(["CARD_AFFLICTION", "HEXED", 1]),
            json!(["CARD_AFFLICTION", "RINGING", 1, 2]),
        ] {
            let mut changed = original.clone();
            changed.piles.get_mut("hand").unwrap()[0].extra = vec![malformed];
            assert!(matches!(
                refuse(&changed),
                BoundaryRefusal::UnrepresentableValue { field, .. }
                    if matches!(field.as_str(), "extra")
            ));
        }
        let mut missing_physical = original;
        missing_physical.piles.get_mut("hand").unwrap()[0].physical_state = None;
        assert!(matches!(
            refuse(&missing_physical),
            BoundaryRefusal::UnrepresentableValue { field, .. }
                if matches!(field.as_str(), "extra")
        ));
    }

