    #[test]
    fn ordered_star_cost_rows_round_trip_negative_energy_and_reject_unknown_shapes() {
        let mut original = fixture();
        let source = &mut original.piles.get_mut("hand").unwrap()[0];
        *source = card(CardId::Whirlwind.as_str(), 0);
        source.physical_state = Some(json!([
            "PHYSICAL_CARD_STATE",
            [],
            0,
            false,
            [[0, false, false], [0, true, true]]
        ]));

        let catalog = HotBoundary::catalog_from_canonical(&original).unwrap();
        let hot = HotBoundary::from_canonical(&original, &catalog).unwrap();
        let instance = hot.card_states.get_ref(0).unwrap();
        assert!(instance.local_cost_modifiers.free_star_cost_this_combat());
        assert_eq!(instance.free_star_cost_this_turn_or_played_rows, 1);
        assert!(instance.local_cost_modifiers.as_slice().is_empty());
        assert_eq!(HotBoundary::to_canonical(&hot, &catalog), original);

        for rows in [
            json!([[0, false, false], [0, false, false]]),
            json!([[0, true, true], [0, false, false]]),
            json!([
                [0, true, true],
                [0, false, false],
                [0, true, true],
                [0, false, false]
            ]),
        ] {
            let mut extended = original.clone();
            extended.piles.get_mut("hand").unwrap()[0].physical_state =
                Some(json!(["PHYSICAL_CARD_STATE", [], 0, false, rows]));
            let hot = HotBoundary::from_canonical(&extended, &catalog).unwrap();
            assert_eq!(HotBoundary::to_canonical(&hot, &catalog), extended);
        }
        for rows in [
            json!([[1, false, false]]),
            json!([[0, true, false]]),
            json!([[0, false, true]]),
        ] {
            let mut malformed = original.clone();
            malformed.piles.get_mut("hand").unwrap()[0].physical_state =
                Some(json!(["PHYSICAL_CARD_STATE", [], 0, false, rows]));
            assert!(matches!(
                HotBoundary::from_canonical(&malformed, &catalog),
                Err(BoundaryRefusal::UnrepresentableValue { .. })
            ));
        }
    }

    #[test]
    fn catalog_previews_only_the_deterministic_infernal_blade_leaf() {
        let mut document = fixture();
        document.piles.get_mut("hand").unwrap()[0] = card("INFERNAL_BLADE", 0);
        document
            .player
            .insert("entropy_card_pool".to_owned(), json!("ironclad"));
        let seeded = Xoshiro256StarStar::from_seed(0);
        document.rng.insert(
            "generation".to_owned(),
            CanonicalRngV2 {
                counter: seeded.counter,
                words: seeded.words,
            },
        );

        let mut pool = INFERNAL_BLADE_ATTACK_POOL_V109;
        let mut preview = seeded;
        preview.shuffle(&mut pool).unwrap();
        let selected = CardIdentity {
            id: pool[0],
            upgrade: 0,
            enchantment: None,
        };
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        assert!(catalog.atom(&selected).is_some());
        let unselected = pool
            .iter()
            .copied()
            .skip(1)
            .map(|id| CardIdentity {
                id,
                upgrade: 0,
                enchantment: None,
            })
            .find(|identity| catalog.atom(identity).is_none())
            .expect("the whole attack pool must not be interned");
        assert_ne!(unselected, selected);
    }

