    #[test]
    fn distraction_previews_every_bounded_shuffle_and_only_its_l0_leaf() {
        let seed = 47;
        for (upgrade, burst, shuffle_count) in [(0, 0, 1usize), (1, 1, 2usize)] {
            let document = distraction_document(seed, upgrade, burst);
            let mut rng = Xoshiro256StarStar::from_seed(seed);
            let mut expected = std::collections::BTreeSet::new();
            for _ in 0..shuffle_count {
                let mut shuffled = DISTRACTION_SKILL_POOL_V1101;
                rng.shuffle(&mut shuffled).unwrap();
                expected.insert(shuffled[0]);
            }
            assert_eq!(
                expected.len(),
                shuffle_count,
                "the fixed seed makes every bounded source/replay leaf distinct"
            );
            let before = document.clone();
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            assert_eq!(document, before, "preview must not mutate canonical RNG");
            for id in &expected {
                assert!(
                    catalog
                        .atom(&CardIdentity {
                            id: *id,
                            upgrade: 0,
                            enchantment: None,
                        })
                        .is_some(),
                    "reachable Distraction leaf must be interned: {id:?}"
                );
                assert!(
                    catalog
                        .atom(&CardIdentity {
                            id: *id,
                            upgrade: 1,
                            enchantment: None,
                        })
                        .is_none(),
                    "Distraction+ changes source cost, never result level: {id:?}"
                );
            }
            assert!(DISTRACTION_SKILL_POOL_V1101.iter().copied().any(|id| {
                !expected.contains(&id)
                    && catalog
                        .atom(&CardIdentity {
                            id,
                            upgrade: 0,
                            enchantment: None,
                        })
                        .is_none()
            }));
        }
    }

    #[test]
    fn generated_burst_widens_the_later_distraction_preview_to_a_fixed_point() {
        let seed = 24;
        let mut document = distraction_document(seed, 0, 0);
        document
            .piles
            .get_mut("hand")
            .unwrap()
            .push(card(CardId::Distraction.as_str(), 101));
        document
            .player
            .insert("next_card_uid".to_owned(), json!(102));
        document
            .player
            .insert("exact_piles".to_owned(), json!(true));

        let mut preview = Xoshiro256StarStar::from_seed(seed);
        let expected = (0..3)
            .map(|_| {
                let mut pool = DISTRACTION_SKILL_POOL_V1101;
                preview.shuffle(&mut pool).unwrap();
                pool[0]
            })
            .collect::<Vec<_>>();
        assert_eq!(
            expected,
            [CardId::Burst, CardId::Backflip, CardId::Blur],
            "seed 24 is the source-derived generated-writer trajectory"
        );

        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        for id in &expected {
            assert!(
                catalog
                    .atom(&CardIdentity {
                        id: *id,
                        upgrade: 0,
                        enchantment: None,
                    })
                    .is_some()
            );
        }
        let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        crate::engine::admit(&document, &state, &catalog).unwrap();
        for uid in [0, 102, 101] {
            let action = crate::engine::legal_actions(&state, &catalog)
                .into_iter()
                .find(|action| matches!(action, crate::engine::Action::Play { uid: live, .. } if *live == uid))
                .unwrap_or_else(|| panic!("missing trajectory play uid {uid}"));
            state = crate::engine::apply_action(&state, &catalog, &action)
                .unwrap()
                .state;
        }
        let generated = state
            .piles
            .get(PileId::Hand)
            .as_slice()
            .iter()
            .filter_map(|card| catalog.spec(card.atom).map(|spec| spec.identity.id))
            .collect::<Vec<_>>();
        assert!(generated.contains(&CardId::Backflip));
        assert!(generated.contains(&CardId::Blur));
    }

