    #[test]
    fn white_noise_preview_counts_only_hand_draw_and_discard_sources() {
        let base = white_noise_document(47, RewardPool::Defect, 0, 0);
        let identities = |document: &CanonicalStateV2| {
            HotBoundary::catalog_from_canonical(document)
                .unwrap()
                .specs()
                .map(|spec| spec.identity)
                .collect::<std::collections::BTreeSet<_>>()
        };
        let hand = identities(&base);
        for pile in ["draw", "discard"] {
            let mut document = base.clone();
            let source = document.piles.get_mut("hand").unwrap().remove(0);
            document
                .piles
                .entry(pile.to_owned())
                .or_default()
                .push(source);
            assert_eq!(identities(&document), hand, "{pile} remains playable");
        }
        for pile in ["exhaust", "play"] {
            let mut document = base.clone();
            let source = document.piles.get_mut("hand").unwrap().remove(0);
            document
                .piles
                .entry(pile.to_owned())
                .or_default()
                .push(source);
            assert_ne!(
                identities(&document),
                hand,
                "{pile} cannot begin another White Noise body"
            );
        }
    }

