    #[test]
    fn catalog_previews_each_bounded_jack_shuffle_and_only_its_exact_prefix() {
        let seed = 47;
        for (upgrade, burst, shuffle_count, prefix) in
            [(0, 0, 1usize, 1usize), (1, 1, 2usize, 2usize)]
        {
            let document = jack_document(seed, upgrade, burst);
            let mut rng = Xoshiro256StarStar::from_seed(seed);
            let mut expected = std::collections::BTreeSet::new();
            for _ in 0..shuffle_count {
                let mut shuffled = JACK_OF_ALL_TRADES_POOL_V1091;
                rng.shuffle(&mut shuffled).unwrap();
                expected.extend(shuffled.into_iter().take(prefix));
            }
            assert!(
                !expected.contains(&CardId::Jackpot),
                "seed is a narrow-prefix control"
            );

            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            for id in &expected {
                assert!(
                    catalog
                        .atom(&CardIdentity {
                            id: *id,
                            upgrade: 0,
                            enchantment: None,
                        })
                        .is_some(),
                    "Jack's reachable prefix leaf must be interned: {id:?}"
                );
            }
            let unselected = JACK_OF_ALL_TRADES_POOL_V1091
                .iter()
                .copied()
                .filter(|id| !expected.contains(id))
                .map(|id| CardIdentity {
                    id,
                    upgrade: 0,
                    enchantment: None,
                })
                .find(|identity| catalog.atom(identity).is_none())
                .expect("a bounded Jack must not intern the whole 49-row pool");
            assert!(!expected.contains(&unselected.id));
        }
    }

    #[test]
    fn jack_preview_is_the_exact_order_union_and_burst_is_catalog_only() {
        let seed = 47;
        let mut document = jack_document(seed, 0, 1);
        let hand = document.piles.get_mut("hand").unwrap();
        let mut upgraded = card("JACK_OF_ALL_TRADES", 101);
        upgraded.upgrade = 1;
        upgraded.uid = Some(101);
        hand.push(upgraded);
        let before = document.clone();

        let mut preview = Xoshiro256StarStar::from_seed(seed);
        let mut reachable = std::collections::BTreeSet::new();
        // Either physical Jack can be played at either shuffle epoch. The
        // L1 copy exposes the second result at that epoch, so prefix two at
        // both positions is the exact union over legal source order. Burst
        // may be consumed by another Skill first; retaining its one possible
        // replay therefore enlarges only the immutable catalog.
        for _ in 0..3 {
            let mut shuffled = JACK_OF_ALL_TRADES_POOL_V1091;
            preview.shuffle(&mut shuffled).unwrap();
            reachable.extend(shuffled.into_iter().take(2));
        }
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        assert_eq!(
            document, before,
            "preview cannot mutate canonical state/RNG"
        );
        for id in &reachable {
            assert!(
                catalog
                    .atom(&CardIdentity {
                        id: *id,
                        upgrade: 0,
                        enchantment: None,
                    })
                    .is_some(),
                "{id:?}"
            );
        }
        assert!(JACK_OF_ALL_TRADES_POOL_V1091.iter().copied().any(|id| {
            !reachable.contains(&id)
                && catalog
                    .atom(&CardIdentity {
                        id,
                        upgrade: 0,
                        enchantment: None,
                    })
                    .is_none()
        }));

        // Canonical pile order is not play order. Swapping the mixed levels
        // must retain the same exact union rather than assigning one prefix
        // width to a particular physical slot.
        let mut swapped = document.clone();
        let hand = swapped.piles.get_mut("hand").unwrap();
        let second = hand.len() - 1;
        hand.swap(0, second);
        let swapped_catalog = HotBoundary::catalog_from_canonical(&swapped).unwrap();
        let identities = |catalog: &Catalog| {
            catalog
                .specs()
                .map(|spec| spec.identity)
                .collect::<std::collections::BTreeSet<_>>()
        };
        assert_eq!(identities(&catalog), identities(&swapped_catalog));
    }

    #[test]
    fn a_jack_prefix_that_reaches_jackpot_interns_its_repeatable_owner_pool() {
        let (seed, selected) = (0..4096)
            .find_map(|seed| {
                let mut rng = Xoshiro256StarStar::from_seed(seed);
                let mut pool = JACK_OF_ALL_TRADES_POOL_V1091;
                rng.shuffle(&mut pool).unwrap();
                (pool[0] == CardId::Jackpot).then_some((seed, pool[0]))
            })
            .expect("one small seed must select Jackpot first");
        assert_eq!(selected, CardId::Jackpot);

        let catalog = HotBoundary::catalog_from_canonical(&jack_document(seed, 0, 0)).unwrap();
        for id in crate::content_tables::JACKPOT_ZERO_COST_POOL_V109 {
            assert!(
                catalog
                    .atom(&CardIdentity {
                        id,
                        upgrade: 0,
                        enchantment: None,
                    })
                    .is_some(),
                "generated non-Exhaust Jackpot reaches every owner-pool leaf: {id:?}"
            );
        }
        assert!(JACK_OF_ALL_TRADES_POOL_V1091.iter().copied().any(|id| {
            id != CardId::Jackpot
                && !crate::content_tables::JACKPOT_ZERO_COST_POOL_V109.contains(&id)
                && catalog
                    .atom(&CardIdentity {
                        id,
                        upgrade: 0,
                        enchantment: None,
                    })
                    .is_none()
        }));
    }

    #[test]
    fn direct_seed_245_jack_closes_discovery_through_its_ironclad_owner() {
        let document = jack_document(245, 0, 0);
        let mut preview = Xoshiro256StarStar::from_seed(245);
        let mut jack_pool = JACK_OF_ALL_TRADES_POOL_V1091;
        preview.shuffle(&mut jack_pool).unwrap();
        assert_eq!(jack_pool[0], CardId::Discovery, "native regression seed");

        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        for id in crate::content_tables::STOKE_CARD_POOL_V109 {
            assert!(
                catalog
                    .atom(&CardIdentity {
                        id,
                        upgrade: 0,
                        enchantment: None,
                    })
                    .is_some(),
                "Jack -> Discovery must intern every Ironclad owner-pool identity: {id:?}"
            );
        }
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert_eq!(crate::engine::admit(&document, &state, &catalog), Ok(()));

        // A nearby bounded seed that does not select Discovery must not gain
        // Discovery's entire pool merely because Discovery exists globally.
        let control = jack_document(47, 0, 0);
        let mut control_preview = Xoshiro256StarStar::from_seed(47);
        let mut control_jack_pool = JACK_OF_ALL_TRADES_POOL_V1091;
        control_preview.shuffle(&mut control_jack_pool).unwrap();
        assert_ne!(control_jack_pool[0], CardId::Discovery);
        let control_catalog = HotBoundary::catalog_from_canonical(&control).unwrap();
        assert!(
            crate::content_tables::STOKE_CARD_POOL_V109
                .iter()
                .copied()
                .any(|id| control_catalog
                    .atom(&CardIdentity {
                        id,
                        upgrade: 0,
                        enchantment: None,
                    })
                    .is_none())
        );
    }

    /// #3382: a lone Jack whose seeded prefix holds Splash closes the complete
    /// pool, so admission's ordering gate no longer counts Jack's own result
    /// as a second consumer beside an incomplete pool (census 7UEE3Y1SPJCY
    /// n22). Both prefix widths are pinned: Splash first for Jack, and Splash
    /// only in the second slot for Jack+. The Splash-free prefix is pinned
    /// unchanged by `catalog_previews_each_bounded_jack_shuffle_and_only_its_exact_prefix`.
    #[test]
    fn a_jack_prefix_that_holds_splash_closes_the_complete_pool() {
        let ordering = crate::engine::MissingCapability::ArgumentShape(
            "jack of all trades generation ordering",
        );
        for (upgrade, slot) in [(0u8, 0usize), (1, 1)] {
            let seed = (0..4096)
                .find(|seed| {
                    let mut rng = Xoshiro256StarStar::from_seed(*seed);
                    let mut pool = JACK_OF_ALL_TRADES_POOL_V1091;
                    rng.shuffle(&mut pool).unwrap();
                    pool[slot] == CardId::Splash && !pool[..slot].contains(&CardId::Splash)
                })
                .expect("a small seed puts Splash in the prefix slot");
            let document = jack_document(seed, upgrade, 0);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            for id in JACK_OF_ALL_TRADES_POOL_V1091 {
                assert!(
                    catalog
                        .atom(&CardIdentity {
                            id,
                            upgrade: 0,
                            enchantment: None,
                        })
                        .is_some(),
                    "L{upgrade} Jack with Splash in its prefix closes the whole pool: {id:?}"
                );
            }
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            if let Err(refusal) = crate::engine::admit(&document, &state, &catalog) {
                assert!(
                    !refusal.contains(ordering),
                    "L{upgrade} Jack must not refuse on its own Splash result: {refusal:?}"
                );
            }

            // The same seed with a Jack whose prefix stops before Splash
            // keeps the narrow prefix: only L1 has a second slot.
            if slot == 1 {
                let narrow = jack_document(seed, 0, 0);
                let narrow_catalog = HotBoundary::catalog_from_canonical(&narrow).unwrap();
                assert!(
                    narrow_catalog
                        .atom(&CardIdentity {
                            id: CardId::Splash,
                            upgrade: 0,
                            enchantment: None,
                        })
                        .is_none(),
                    "an L0 Jack whose one-row prefix is not Splash stays narrow"
                );
            }
        }
    }

    /// #3382: a Skill Potion can mint White Noise, which then mints any owner
    /// Power from any stream position (census 7UEE3Y1SPJCY n10 refused
    /// mid-fight on an uninterned Spinner). Without the potion the Power pool
    /// is not interned (control). Distraction, the other one-row drawer, is
    /// Event rarity, so no potion offers it.
    #[test]
    fn a_potion_minted_white_noise_closes_its_power_pool() {
        let mut document = white_noise_document(47, RewardPool::Defect, 0, 0);
        document.piles.get_mut("hand").unwrap()[0] =
            fixture().piles.get("hand").unwrap()[0].clone();
        let bare = HotBoundary::catalog_from_canonical(&document).unwrap();
        document
            .player
            .insert("potion_slots".to_owned(), json!(["SKILL_POTION"]));
        document
            .player
            .insert("potions".to_owned(), json!(["SKILL_POTION"]));
        document
            .player
            .insert("fully_unlocked_potion_pool".to_owned(), Value::Bool(true));
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        assert!(
            catalog.is_reachable(CardIdentity {
                id: CardId::WhiteNoise,
                upgrade: 0,
                enchantment: None,
            }),
            "the Defect Skill Potion offers White Noise"
        );
        let pool = catalog
            .owner_type_generation_pool(RewardPool::Defect, crate::content_tables::CardType::Power);
        assert!(pool.contains(&CardId::Spinner));
        let l0 = |catalog: &Catalog, id: CardId| {
            catalog
                .atom(&CardIdentity {
                    id,
                    upgrade: 0,
                    enchantment: None,
                })
                .is_some()
        };
        for id in &pool {
            assert!(
                l0(&catalog, *id),
                "a potion-minted White Noise can mint {id:?}"
            );
        }
        assert!(
            pool.iter().any(|id| !l0(&bare, *id)),
            "without the potion the Power pool is not interned (control)"
        );
        assert!(
            crate::content_tables::card_row(CardId::Distraction, 0)
                .is_some_and(|row| row.rarity == crate::content_tables::CardRarity::Event),
            "Distraction must stay outside every potion's card-choice pool"
        );
    }

    /// #3382: Drain Power upgrades a Discard card, and a Vexing Puzzlebox card
    /// reaches Discard, so every upgradable row of the relic's owner pool
    /// needs its L1 atom. The relic pool is interned after the card-owned
    /// upgrade closure, which is why census WV9GZBQ50ZHH n36 refused `Drain
    /// Power discard upgrade closure`. Without an upgrade writer the relic
    /// pool stays at L0 (control).
    #[test]
    fn drain_power_closes_the_upgrades_of_relic_generated_cards() {
        let document = |drain_power: bool| {
            let mut document = white_noise_document(47, RewardPool::Necrobinder, 0, 0);
            let hand = document.piles.get_mut("hand").unwrap();
            hand[0] = if drain_power {
                card("DRAIN_POWER", 900)
            } else {
                fixture().piles.get("hand").unwrap()[0].clone()
            };
            document.player.insert(
                "relics_entering".to_owned(),
                json!(["RELIC.VEXING_PUZZLEBOX"]),
            );
            document
                .player
                .insert("relics_entering_dispatch_ordered".to_owned(), json!(true));
            document
                .player
                .insert("vexing_puzzlebox".to_owned(), json!(true));
            document
        };
        let upgraded_leaves = |catalog: &Catalog| {
            catalog
                .owner_generation_pool(RewardPool::Necrobinder)
                .into_iter()
                .filter(|id| {
                    crate::engine::cards::native_card_is_upgradable(CardIdentity {
                        id: *id,
                        upgrade: 0,
                        enchantment: None,
                    })
                })
                .map(|id| {
                    catalog
                        .atom(&CardIdentity {
                            id,
                            upgrade: 1,
                            enchantment: None,
                        })
                        .is_some()
                })
                .collect::<Vec<_>>()
        };

        let catalog = HotBoundary::catalog_from_canonical(&document(true)).unwrap();
        let leaves = upgraded_leaves(&catalog);
        assert!(!leaves.is_empty());
        assert!(
            leaves.iter().all(|present| *present),
            "Drain Power closes every Vexing Puzzlebox leaf's upgrade"
        );
        let state = HotBoundary::from_canonical(&document(true), &catalog).unwrap();
        if let Err(refusal) = crate::engine::admit(&document(true), &state, &catalog) {
            assert!(
                !refusal.contains(crate::engine::MissingCapability::ArgumentShape(
                    "Drain Power discard upgrade closure"
                )),
                "{refusal:?}"
            );
        }

        let control = HotBoundary::catalog_from_canonical(&document(false)).unwrap();
        assert!(
            upgraded_leaves(&control).iter().any(|present| !present),
            "without an upgrade writer the relic pool stays at L0"
        );
    }

    #[test]
    fn generated_jack_discovery_cycle_closes_once_and_admission_stays_exact() {
        // Spectrum Shift's repeatable pool contains Jack. Jack's full result
        // pool contains Discovery; Regent Discovery can generate Bundle of
        // Joy, whose pool contains Jack again. Building this canonical state
        // proves the shared identity guard terminates that real cycle.
        let mut document = fixture();
        document.piles.get_mut("hand").unwrap()[0] = card(CardId::SpectrumShift.as_str(), 991);
        document
            .player
            .insert("reward_card_pool".to_owned(), json!("Regent"));
        document
            .player
            .insert("entropy_card_pool".to_owned(), json!("regent"));
        document.player.insert(
            "spectrum_shift_generation_pool".to_owned(),
            Value::Array(
                REGENT_COLORLESS_GENERATION_POOL_V1101
                    .iter()
                    .map(|id| Value::from(id.as_str()))
                    .collect(),
            ),
        );
        document.player.insert(
            "splash_unlock_epochs".to_owned(),
            Value::Array(
                FULLY_UNLOCKED_CARD_POOL_EPOCHS
                    .iter()
                    .copied()
                    .map(Value::from)
                    .collect(),
            ),
        );
        let seeded = Xoshiro256StarStar::from_seed(245);
        document.rng.insert(
            RngStream::Generation.as_str().to_owned(),
            CanonicalRngV2 {
                counter: seeded.counter,
                words: seeded.words,
            },
        );

        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        for id in crate::content_tables::REGENT_CARD_GENERATION_POOL_V1101 {
            assert!(
                catalog
                    .atom(&CardIdentity {
                        id,
                        upgrade: 0,
                        enchantment: None,
                    })
                    .is_some(),
                "generated Jack -> Discovery omitted Regent owner-pool identity {id:?}"
            );
        }
        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
        let refusal = crate::engine::admit(&document, &state, &catalog).unwrap_err();
        // #2542: the owner axis is closed, so Calamity's blanket
        // "generation provenance" hole is gone for Regent. #2667 converted
        // Glimmer's nested Draw into an owned CardPlay tail, closing the
        // last unconverted card-draw source in this catalog, so the
        // Stratagem owner wall falls with it: every remaining card-program
        // Draw now parks under a persisted owner. The quotient's remaining
        // typed gap is the terminal star/orb AfterEnergyReset order.
        assert!(
            !refusal.contains(crate::engine::admission::MissingCapability::ArgumentShape(
                "foregone selection"
            )),
            "Foregone's persisted selector must not hide the real Regent gap: {refusal}"
        );
        assert!(
            !refusal.contains(crate::engine::admission::MissingCapability::ArgumentShape(
                "stratagem selection"
            )),
            "Glimmer's owned tail owns every card-program Stratagem shuffle here: {refusal}"
        );
        assert!(
            refusal.contains(crate::engine::admission::MissingCapability::ArgumentShape(
                "terminal star/orb AfterEnergyReset order"
            )),
            "Regent's incomplete repeatable Attack quotient must stay typed: {refusal}"
        );
        for stale_hole in [
            "Discovery generation closure",
            "jack of all trades generation closure",
        ] {
            assert!(
                !refusal.contains(crate::engine::admission::MissingCapability::ArgumentShape(
                    stale_hole
                ))
            );
        }

        let mut wrong_owner = document;
        wrong_owner
            .player
            .insert("entropy_card_pool".to_owned(), json!("ironclad"));
        let catalog = HotBoundary::catalog_from_canonical(&wrong_owner).unwrap();
        let state = HotBoundary::from_canonical(&wrong_owner, &catalog).unwrap();
        assert!(
            crate::engine::admit(&wrong_owner, &state, &catalog)
                .unwrap_err()
                .contains(crate::engine::admission::MissingCapability::ArgumentShape(
                    "Spectrum Shift generation provenance"
                )),
            "owner drift remains a provenance refusal, not a relaxed closure"
        );
    }

