    #[test]
    fn auto_body_in_a_former_source_pile_is_rejected() {
        for pile in [PileId::Hand, PileId::Draw, PileId::Discard, PileId::Exhaust] {
            let (state, catalog) = pending_replay_state(pile, false, true);
            let before = state.clone();
            let wire = HotBoundary::to_canonical(&state, &catalog);
            assert!(
                HotBoundary::from_canonical(&wire, &catalog).is_err(),
                "{pile:?}"
            );
            assert!(crate::engine::legal_actions(&state, &catalog).is_empty());
            assert_eq!(state, before);
        }
    }

    #[test]
    fn pending_manual_and_auto_play_sources_round_trip_and_resume() {
        for (source_pile, manual, force_exhaust) in [
            (PileId::Play, true, false),
            (PileId::Play, false, false),
            (PileId::Play, false, true),
        ] {
            let (state, catalog) = pending_replay_state(source_pile, manual, force_exhaust);
            let canonical = HotBoundary::to_canonical(&state, &catalog);
            let card_play = canonical.continuations.last().unwrap();
            assert_eq!(
                card_play.fields["star_spent"],
                Value::from(if manual { 2 } else { 0 })
            );
            assert_eq!(
                card_play.fields["result_location"],
                if force_exhaust {
                    serde_json::json!(["exhaust", "bottom"])
                } else {
                    serde_json::json!(["discard", "bottom"])
                }
            );
            let reloaded = HotBoundary::from_canonical(&canonical, &catalog).unwrap();
            assert_eq!(reloaded, state, "{source_pile:?} source survives reload");

            let actions = crate::engine::legal_actions(&state, &catalog);
            assert_eq!(crate::engine::legal_actions(&reloaded, &catalog), actions);
            // This legacy shape remains a pure wire round-trip control. The
            // executable imported path below is rooted by the public action.
            // A listener may update the live physical payload between replay
            // suspension and the next selection. The frozen continuation owns
            // execution identity, while routing must retain the uniquely found
            // live card rather than requiring payload equality with the frame.
        }

        let (state, catalog) = pending_replay_state(PileId::Play, true, false);
        let state = authenticate_pending_manual_replay(state, &catalog);
        let canonical = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let reload_catalog = HotBoundary::catalog_from_canonical(&canonical).unwrap();
        let reloaded = HotBoundary::from_canonical(&canonical, &reload_catalog).unwrap();
        crate::engine::admit(&canonical, &reloaded, &reload_catalog).unwrap();
        let actions = crate::engine::legal_actions(&reloaded, &reload_catalog);
        assert_eq!(
            actions,
            vec![
                crate::engine::Action::Select {
                    answer: crate::engine::SelectionAnswer::CardUid(3),
                },
                crate::engine::Action::Select {
                    answer: crate::engine::SelectionAnswer::CardUid(6),
                },
            ]
        );
        let next = crate::engine::apply_action(&reloaded, &reload_catalog, &actions[0])
            .unwrap()
            .state;
        assert!(next.pending.is_none());
        assert!(next.frames.is_empty());
        assert!(
            next.piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .any(|card| card.uid == 3)
        );
    }

    #[test]
    fn pending_monologue_latch_and_strength_ledger_round_trip_and_reject_forgeries() {
        let (mut state, catalog) = pending_replay_state(PileId::Play, true, false);
        state.fanouts.set_next_after_side_turn_end_power_uid(1);
        assert!(
            state
                .fanouts
                .set_monologue_instances(&[crate::hot::MonologueInstance {
                    uid: 0,
                    amount: 1,
                    power: 1,
                    strength_applied: 3,
                }])
        );
        state.powers.set(PowerId::Monologue, SlotWire::Int, 1);
        assert!(state.fanouts.set_after_side_turn_end_power_order(&[
            crate::hot::AfterSideTurnEndPowerEntry {
                token: crate::hot::AfterSideTurnEndPowerToken::Monologue,
                uid: 0,
            },
        ]));
        assert!(state.fanouts.set_after_card_played_power_order(&[
            crate::hot::AfterCardPlayedPowerEntry {
                token: crate::hot::AfterCardPlayedPowerToken::Monologue,
                uid: 0,
            },
        ]));
        update_pending_record(&mut state, |record| {
            record.monologue = true;
            record.monologue_latches = vec![(0, 1)];
            record.instanced_power_uid_at_before = Some(1);
        });
        let state = authenticate_pending_manual_replay(state, &catalog);

        let canonical = HotBoundary::to_canonical(&state, &catalog);
        assert_eq!(canonical.player["monologue"], json!(1));
        assert_eq!(canonical.player["monologue_strength_applied"], json!(4));
        let card_play_index = canonical.continuations.len() - 1;
        let latch = canonical.continuations[card_play_index].fields["latch"]
            .as_array()
            .unwrap();
        assert_eq!(latch.len(), 11);
        assert_eq!(latch[9], json!(1));
        let reloaded = HotBoundary::from_canonical(&canonical, &catalog).unwrap();
        assert_eq!(reloaded, state);
        assert!(crate::engine::admit(&canonical, &reloaded, &catalog).is_ok());
        assert_eq!(
            HotBoundary::to_canonical(&reloaded, &catalog),
            canonical,
            "the encoder preserves every non-Monologue latch cell too"
        );

        let mut missing_live_latch = canonical.clone();
        missing_live_latch.continuations[card_play_index]
            .fields
            .get_mut("latch")
            .unwrap()
            .as_array_mut()
            .unwrap()[9] = json!(0);
        assert!(HotBoundary::from_canonical(&missing_live_latch, &catalog).is_err());

        for forged_value in [json!(true), json!("1"), Value::Null, json!(-1), json!(2)] {
            let mut forged = canonical.clone();
            forged.continuations[card_play_index]
                .fields
                .get_mut("latch")
                .unwrap()
                .as_array_mut()
                .unwrap()[9] = forged_value;
            assert!(HotBoundary::from_canonical(&forged, &catalog).is_err());
        }
        let mut wrong_length = canonical.clone();
        wrong_length.continuations[card_play_index]
            .fields
            .get_mut("latch")
            .unwrap()
            .as_array_mut()
            .unwrap()
            .pop();
        assert!(HotBoundary::from_canonical(&wrong_length, &catalog).is_err());

        let (plain_state, plain_catalog) = pending_replay_state(PileId::Play, true, false);
        let mut forged_live = HotBoundary::to_canonical(&plain_state, &plain_catalog);
        forged_live.continuations[0]
            .fields
            .get_mut("latch")
            .unwrap()
            .as_array_mut()
            .unwrap()[9] = json!(1);
        assert!(HotBoundary::from_canonical(&forged_live, &plain_catalog).is_err());
    }

    #[test]
    fn pending_void_form_carrier_round_trips_and_request_requires_replay_provenance() {
        let (mut state, catalog) = pending_replay_state(PileId::Play, true, false);
        crate::engine::play::prepare_after_card_played_scalar_write(
            &mut state,
            PowerId::VoidForm,
            0,
            2,
        )
        .unwrap();
        state.powers.set(PowerId::VoidForm, SlotWire::Int, 2);
        state.fanouts.set_void_form_hooks_registered(true);
        assert!(
            state
                .fanouts
                .set_void_form_cards_played_this_turn(999_999_999)
        );
        let state = authenticate_pending_manual_replay(state, &catalog);
        let canonical = HotBoundary::to_canonical(&state, &catalog);
        assert_eq!(canonical.player["void_form"], json!(2));
        assert_eq!(
            canonical.player["void_form_cards_played_this_turn"],
            json!(999_999_999)
        );
        assert!(!canonical.player.contains_key("end_turn_requested"));
        let reloaded = HotBoundary::from_canonical(&canonical, &catalog).unwrap();
        assert_eq!(reloaded, state);
        assert!(crate::engine::admit(&canonical, &reloaded, &catalog).is_ok());

        // The runtime-only deferred-service path is pinned by
        // engine::tests::void_form_deferred_end_turn_waits_for_replay_resume_then_services_once.
        // An imported request must be reproduced by its ActionReplay root;
        // appending it to an unrelated parked play is a forged transcript.
        let mut forged = canonical;
        forged
            .player
            .insert("end_turn_requested".to_owned(), json!(true));
        assert!(HotBoundary::from_canonical(&forged, &catalog).is_err());
    }

    #[test]
    fn tender_and_void_form_listener_carriers_coexist_through_replay_completion() {
        let (plain_state, plain_catalog) = pending_replay_state(PileId::Play, true, false);
        let mut canonical = HotBoundary::to_canonical(&plain_state, &plain_catalog);
        canonical.player.insert("tender".to_owned(), json!(1));
        canonical
            .player
            .insert("tender_cards_played".to_owned(), json!(2));
        append_singleton_side_end_row(&mut canonical, "tender");
        canonical.player.insert("void_form".to_owned(), json!(2));
        canonical
            .player
            .insert("void_form_cards_played_this_turn".to_owned(), json!(7));
        append_singleton_after_card_played_row(&mut canonical, "void_form");
        canonical.monsters.push(BTreeMap::from([
            ("kind".to_owned(), json!("HUNTER_KILLER")),
            ("hp".to_owned(), json!(126)),
            ("max_hp".to_owned(), json!(126)),
            ("uid".to_owned(), json!(23)),
            ("next_move".to_owned(), json!("BITE_MOVE")),
            (
                "move_log".to_owned(),
                json!(["TENDERIZING_GOOP_MOVE", "BITE_MOVE"]),
            ),
        ]));

        let mut catalog_document = canonical.clone();
        catalog_document.continuations.clear();
        catalog_document.player.remove("pending");
        let catalog = HotBoundary::catalog_from_canonical(&catalog_document).unwrap();
        let state = HotBoundary::from_canonical(&canonical, &catalog).unwrap();
        let state = authenticate_pending_manual_replay(state, &catalog);
        let canonical = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        assert!(crate::engine::admit(&canonical, &state, &catalog).is_ok());
        assert!(pending_record(&state).tender);
        assert!(crate::steps::regent_uncommon::void_form_private_state_is_exact(&state));
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), canonical);

        let action = crate::engine::legal_actions(&state, &catalog)
            .into_iter()
            .next()
            .expect("replay selection remains legal");
        let result = crate::engine::apply_action(&state, &catalog, &action).unwrap();
        assert_eq!(result.state.fanouts.tender_cards_played(), 4);
        assert_eq!(result.state.fanouts.void_form_cards_played_this_turn(), 8);
        assert_eq!(result.state.powers.value(PowerId::Strength), -2);
        assert_eq!(result.state.powers.value(PowerId::Dexterity), -2);
    }

    #[test]
    fn pending_tender_latch_is_derived_round_trips_resumes_and_rejects_mismatch() {
        let (plain_state, plain_catalog) = pending_replay_state(PileId::Play, true, false);
        let mut canonical = HotBoundary::to_canonical(&plain_state, &plain_catalog);
        canonical.player.insert("tender".to_owned(), json!(1));
        canonical
            .player
            .insert("tender_cards_played".to_owned(), json!(2));
        append_singleton_side_end_row(&mut canonical, "tender");
        canonical.monsters.push(BTreeMap::from([
            ("kind".to_owned(), json!("HUNTER_KILLER")),
            ("hp".to_owned(), json!(126)),
            ("max_hp".to_owned(), json!(126)),
            ("uid".to_owned(), json!(23)),
            ("next_move".to_owned(), json!("BITE_MOVE")),
            (
                "move_log".to_owned(),
                json!(["TENDERIZING_GOOP_MOVE", "BITE_MOVE"]),
            ),
        ]));
        let mut catalog_document = canonical.clone();
        catalog_document.continuations.clear();
        catalog_document.player.remove("pending");
        let catalog = HotBoundary::catalog_from_canonical(&catalog_document).unwrap();
        let state = HotBoundary::from_canonical(&canonical, &catalog).unwrap();
        let state = authenticate_pending_manual_replay(state, &catalog);
        let canonical = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        assert!(pending_record(&state).tender);
        assert_eq!(
            canonical.continuations.last().unwrap().fields["latch"][10],
            json!(0),
            "Tender's internal routing bit is derived, never a new wire field"
        );
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), canonical);
        assert_eq!(
            HotBoundary::from_canonical(&canonical, &catalog).unwrap(),
            state
        );
        let action = crate::engine::legal_actions(&state, &catalog)
            .into_iter()
            .next()
            .expect("replay selection remains legal");
        let result = crate::engine::apply_action(&state, &catalog, &action).unwrap();
        assert_eq!(result.state.fanouts.tender_cards_played(), 4);
        assert_eq!(result.state.powers.value(PowerId::Strength), -2);
        assert_eq!(result.state.powers.value(PowerId::Dexterity), -2);

        let mut missing_hot = state.clone();
        update_pending_record(&mut missing_hot, |record| record.tender = false);
        assert!(HotBoundary::try_to_canonical(&missing_hot, &catalog).is_err());

        let mut malformed_serpent_wire = canonical.clone();
        let card_play_index = malformed_serpent_wire.continuations.len() - 1;
        malformed_serpent_wire.continuations[card_play_index]
            .fields
            .get_mut("latch")
            .unwrap()
            .as_array_mut()
            .unwrap()[10] = json!(-1);
        assert!(HotBoundary::from_canonical(&malformed_serpent_wire, &catalog).is_err());

        let mut forged_extra = plain_state;
        update_pending_record(&mut forged_extra, |record| record.tender = true);
        assert!(HotBoundary::try_to_canonical(&forged_extra, &plain_catalog).is_err());
    }

    #[test]
    fn pending_top_routes_round_trip_after_listener_state_changes() {
        for route in [CardResultRoute::DrawTop, CardResultRoute::ExhaustTop] {
            let (mut state, catalog) = pending_replay_state(PileId::Play, true, false);
            if route == CardResultRoute::ExhaustTop {
                state.powers.set(PowerId::Corruption, SlotWire::Bool, 1);
                assert!(
                    state
                        .fanouts
                        .set_result_location_power_order(&[PowerId::Corruption])
                );
            }
            update_pending_record(&mut state, |record| record.result_route = route);

            let canonical = HotBoundary::to_canonical(&state, &catalog);
            assert_eq!(
                canonical.continuations[0].fields["result_location"],
                match route {
                    CardResultRoute::DrawTop => serde_json::json!(["draw", "top"]),
                    CardResultRoute::ExhaustTop => serde_json::json!(["exhaust", "top"]),
                    _ => unreachable!(),
                }
            );
            assert_eq!(
                HotBoundary::from_canonical(&canonical, &catalog).unwrap(),
                state,
                "the frozen Top position survives consumed and live listener state"
            );
        }
    }

