    #[test]
    fn replay_choice_is_one_exact_live_physical_card_snapshot() {
        let (state, catalog) = pending_replay_state(PileId::Play, true, false);
        let canonical = HotBoundary::to_canonical(&state, &catalog);
        assert_eq!(
            HotBoundary::from_canonical(&canonical, &catalog).unwrap(),
            state
        );

        for (field, forged) in [
            ("uid", json!(state.next_card_uid)),
            (
                "physical_state",
                json!(["PHYSICAL_CARD_STATE", [], 1, false, []]),
            ),
            ("local_keywords", json!(["retain"])),
            ("transient_keywords", json!(["retain"])),
            ("sovereign_blade", json!([1, 2, 3])),
            ("extra", json!(["forged"])),
        ] {
            let mut malformed = canonical.clone();
            malformed.continuations[0]
                .fields
                .get_mut("choice")
                .and_then(Value::as_object_mut)
                .expect("projected replay choice is a card")
                .insert(field.to_owned(), forged);
            assert!(
                HotBoundary::from_canonical(&malformed, &catalog).is_err(),
                "forged replay field {field} was accepted"
            );
        }

        let mut missing = canonical.clone();
        missing.piles.get_mut("exhaust").unwrap().clear();
        assert!(HotBoundary::from_canonical(&missing, &catalog).is_err());

        let mut duplicated = canonical;
        let duplicate = duplicated.piles["exhaust"][0].clone();
        duplicated
            .piles
            .entry("draw".to_owned())
            .or_default()
            .push(duplicate);
        assert!(HotBoundary::from_canonical(&duplicated, &catalog).is_err());

        let (state, _) = pending_replay_state(PileId::Play, true, false);
        let mut enchanted_active = HotBoundary::to_canonical(&state, &catalog);
        enchanted_active.piles.get_mut("play").unwrap()[0].enchantment =
            Some(json!(["MOMENTUM", 1]));
        let enchanted_catalog = HotBoundary::catalog_from_canonical(&enchanted_active).unwrap();
        assert!(
            HotBoundary::from_canonical(&enchanted_active, &enchanted_catalog).is_err(),
            "an enchanted owner must refuse before publishing its Replay selection"
        );
    }

    #[test]
    fn pending_selection_expos_round_trips_zero_and_nonzero_and_rejects_malformed_values() {
        let (mut state, catalog) = pending_replay_state(PileId::Play, true, false);
        for expos in [0, 3] {
            update_pending_record(&mut state, |record| record.expos = Some(expos));
            let canonical = HotBoundary::to_canonical(&state, &catalog);
            assert_eq!(canonical.continuations[0].fields["expos"], expos);
            assert_eq!(
                HotBoundary::from_canonical(&canonical, &catalog).unwrap(),
                state
            );
        }

        let canonical = HotBoundary::to_canonical(&state, &catalog);
        for malformed_expos in [json!(-1), json!(10), json!(1.5), json!("3")] {
            let mut malformed_document = canonical.clone();
            malformed_document.continuations[0]
                .fields
                .insert("expos".to_owned(), malformed_expos);
            let unchanged = malformed_document.clone();
            assert!(HotBoundary::from_canonical(&malformed_document, &catalog).is_err());
            assert_eq!(malformed_document, unchanged);
        }

        let mut missing = canonical.clone();
        missing.continuations[0].fields.remove("expos");
        let unchanged = missing.clone();
        assert!(HotBoundary::from_canonical(&missing, &catalog).is_err());
        assert_eq!(missing, unchanged);

        let mut missing_exact_mode = canonical.clone();
        missing_exact_mode.player.remove("exact_piles");
        let unchanged = missing_exact_mode.clone();
        assert!(HotBoundary::from_canonical(&missing_exact_mode, &catalog).is_err());
        assert_eq!(missing_exact_mode, unchanged);

        let (auto_state, auto_catalog) = pending_replay_state(PileId::Exhaust, false, true);
        let mut invented = HotBoundary::to_canonical(&auto_state, &auto_catalog);
        invented.continuations[0]
            .fields
            .insert("expos".to_owned(), json!(0));
        let unchanged = invented.clone();
        assert!(HotBoundary::from_canonical(&invented, &auto_catalog).is_err());
        assert_eq!(invented, unchanged);
    }

    #[test]
    fn malformed_pending_source_or_ambiguous_active_uid_refuses_atomically() {
        let (state, catalog) = pending_replay_state(PileId::Play, true, false);
        let state = authenticate_pending_manual_replay(state, &catalog);
        let action = crate::engine::legal_actions(&state, &catalog)[0];

        let mut ambiguous = state.clone();
        let active = *ambiguous
            .piles
            .get(PileId::Play)
            .as_slice()
            .iter()
            .find(|card| card.uid == 1)
            .unwrap();
        ambiguous
            .piles
            .get_mut(PileId::Exhaust)
            .make_mut()
            .push(active);
        let before = ambiguous.clone();
        assert_eq!(
            crate::engine::apply_action(&ambiguous, &catalog, &action),
            Err(crate::engine::EngineRefusal::ActionNotLegal(
                "public action legality"
            ))
        );
        assert_eq!(ambiguous, before);

        let mut missing = state.clone();
        missing
            .piles
            .get_mut(PileId::Play)
            .make_mut()
            .retain(|card| card.uid != 1);
        let before = missing.clone();
        assert_eq!(
            crate::engine::apply_action(&missing, &catalog, &action),
            Err(crate::engine::EngineRefusal::ActionNotLegal(
                "public action legality"
            ))
        );
        assert_eq!(missing, before);

        let (manual, manual_catalog) = pending_replay_state(PileId::Play, true, false);
        let mut wrong_source = HotBoundary::to_canonical(&manual, &manual_catalog);
        let active = wrong_source.piles.get_mut("play").unwrap().pop().unwrap();
        wrong_source
            .piles
            .entry("exhaust".to_owned())
            .or_default()
            .push(active);
        let unchanged = wrong_source.clone();
        assert!(HotBoundary::from_canonical(&wrong_source, &manual_catalog).is_err());
        assert_eq!(wrong_source, unchanged);
    }

