    fn nonpending_defend_frame(
        uid: u32,
        stage: crate::hot::CardPlayStage,
        step_count: usize,
    ) -> crate::hot::CardPlayRecord {
        let mut record = crate::hot::CardPlayRecord::pending_for_test(uid);
        record.pending_choice = false;
        record.selection_kind = None;
        record.selection_amount = 0;
        record.stage = stage;
        record.next_step = match stage {
            crate::hot::CardPlayStage::StartBody => 0,
            crate::hot::CardPlayStage::Body => 0,
            _ => u32::try_from(step_count).unwrap(),
        };
        record.latch_kind = match stage {
            crate::hot::CardPlayStage::StartBody => crate::hot::CardPlayLatchKind::Empty,
            crate::hot::CardPlayStage::Body
            | crate::hot::CardPlayStage::AfterBody
            | crate::hot::CardPlayStage::AfterEnchantment => crate::hot::CardPlayLatchKind::Raw,
            crate::hot::CardPlayStage::AfterImitation
            | crate::hot::CardPlayStage::AfterNormalHook => crate::hot::CardPlayLatchKind::Post,
        };
        record
    }

    fn nested_card_play_boundary_state() -> (HotState, Catalog) {
        let (mut state, catalog) = pending_replay_state(PileId::Play, false, true);
        let child = pending_record(&state).to_owned();
        let defend_position = state
            .piles
            .get(PileId::Hand)
            .as_slice()
            .iter()
            .position(|card| {
                catalog
                    .spec(card.atom)
                    .is_some_and(|spec| matches!(spec.identity.id, CardId::DefendIronclad))
            })
            .unwrap();
        let defend = state
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .remove(defend_position);
        let mut second = defend;
        second.uid = state.next_card_uid;
        state.next_card_uid += 1;
        let active = state.piles.get_mut(PileId::Play).make_mut().pop().unwrap();
        state
            .piles
            .get_mut(PileId::Play)
            .make_mut()
            .extend([defend, second, active]);
        let step_count = catalog.spec(defend.atom).unwrap().row.steps.len();
        state.frames = Frames::new();
        state.pending = None;
        let outer = nonpending_defend_frame(
            defend.uid,
            crate::hot::CardPlayStage::AfterImitation,
            step_count,
        );
        state.frames.push_card_play(&outer).unwrap();
        let middle =
            nonpending_defend_frame(second.uid, crate::hot::CardPlayStage::Body, step_count);
        state.frames.push_card_play(&middle).unwrap();
        let child_record = state.frames.push_card_play(&child).unwrap();
        state.pending = Some(std::sync::Arc::new(crate::hot::PendingSelection {
            frame_uid: child.uid,
            frame_record: child_record,
        }));
        (state, catalog)
    }

    #[test]
    fn every_nonpending_card_play_stage_has_an_exact_canonical_inverse() {
        for stage in [
            crate::hot::CardPlayStage::StartBody,
            crate::hot::CardPlayStage::Body,
            crate::hot::CardPlayStage::AfterBody,
            crate::hot::CardPlayStage::AfterEnchantment,
            crate::hot::CardPlayStage::AfterImitation,
            crate::hot::CardPlayStage::AfterNormalHook,
        ] {
            let (mut state, catalog) = pending_replay_state(PileId::Exhaust, false, true);
            let defend_position = state
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .position(|card| {
                    catalog
                        .spec(card.atom)
                        .is_some_and(|spec| matches!(spec.identity.id, CardId::DefendIronclad))
                })
                .unwrap();
            let defend = state
                .piles
                .get_mut(PileId::Hand)
                .make_mut()
                .remove(defend_position);
            state.piles.get_mut(PileId::Play).make_mut().push(defend);
            let steps = catalog.spec(defend.atom).unwrap().row.steps.len();
            state.frames = Frames::new();
            state.pending = None;
            let record = nonpending_defend_frame(defend.uid, stage, steps);
            state.frames.push_card_play(&record).unwrap();
            let canonical = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
            assert!(crate::engine::admit(&canonical, &state, &catalog).is_err());
            assert!(crate::engine::legal_actions(&state, &catalog).is_empty());
            assert_eq!(
                crate::engine::apply_action(&state, &catalog, &crate::engine::Action::EndTurn),
                Err(crate::engine::EngineRefusal::ContinuationNotModeled)
            );
            assert_eq!(canonical.player["active_cards"], json!([defend.uid]));
            assert_eq!(canonical.player["active_play"], json!([0]));
            let stage_name = match stage {
                crate::hot::CardPlayStage::StartBody => "start_body",
                crate::hot::CardPlayStage::Body => "body",
                crate::hot::CardPlayStage::AfterBody => "after_body",
                crate::hot::CardPlayStage::AfterEnchantment => "after_enchantment",
                crate::hot::CardPlayStage::AfterImitation => "after_imitation",
                crate::hot::CardPlayStage::AfterNormalHook => "after_normal_hook",
            };
            assert_eq!(canonical.continuations[0].fields["stage"], stage_name);
            assert!(
                !canonical.continuations[0]
                    .fields
                    .contains_key("body_receipt")
            );
            assert_eq!(
                HotBoundary::from_canonical(&canonical, &catalog)
                    .unwrap_or_else(|refusal| panic!("stage {stage:?}: {refusal:?}")),
                state,
                "stage {stage:?}"
            );
            if stage == crate::hot::CardPlayStage::AfterImitation {
                let mut unavailable_wire_snapshot = canonical.clone();
                let listener_uid = u64::from(state.next_card_uid);
                unavailable_wire_snapshot
                    .piles
                    .entry("draw".to_owned())
                    .or_default()
                    .push(card(CardId::Pinpoint.as_str(), listener_uid));
                unavailable_wire_snapshot
                    .player
                    .insert("next_card_uid".to_owned(), json!(listener_uid + 1));
                let listener_catalog =
                    HotBoundary::catalog_from_canonical(&unavailable_wire_snapshot).unwrap();
                assert!(
                    HotBoundary::from_canonical(&unavailable_wire_snapshot, &listener_catalog,)
                        .is_err(),
                    "AfterImitation import cannot guess the missing pre-child listener snapshot"
                );
            }

            for (field, value) in [
                ("plays", json!(0)),
                ("plays", json!(257)),
                ("plays", json!(u32::MAX)),
                (
                    "play_index",
                    canonical.continuations[0].fields["plays"].clone(),
                ),
                ("play_index", json!(u32::MAX)),
                ("spent", json!(-1)),
                ("spent", json!(i32::from(i16::MAX) + 1)),
            ] {
                let mut malformed = canonical.clone();
                malformed.continuations[0]
                    .fields
                    .insert(field.to_owned(), value);
                assert!(
                    HotBoundary::from_canonical(&malformed, &catalog).is_err(),
                    "stage {stage:?} accepted malformed {field}"
                );
            }
            let mut manual_force_exhaust = canonical.clone();
            manual_force_exhaust.continuations[0]
                .fields
                .insert("force_exhaust".to_owned(), json!(true));
            assert!(HotBoundary::from_canonical(&manual_force_exhaust, &catalog).is_err());

            for receipt in [json!([]), json!([["eidolon", 1]])] {
                let mut malformed = canonical.clone();
                malformed.continuations[0]
                    .fields
                    .insert("body_receipt".to_owned(), receipt);
                assert!(
                    HotBoundary::from_canonical(&malformed, &catalog).is_err(),
                    "stage {stage:?} accepted an explicit body receipt"
                );
            }
            for source in ["AnyAlly", "PhysicalCardPick", "hellraiser", "stampede"] {
                let mut malformed = canonical.clone();
                malformed.continuations[0]
                    .fields
                    .insert("source".to_owned(), json!(source));
                assert!(
                    HotBoundary::from_canonical(&malformed, &catalog).is_err(),
                    "stage {stage:?} accepted open source {source}"
                );
            }
            let oblivion_slot = match stage {
                crate::hot::CardPlayStage::Body
                | crate::hot::CardPlayStage::AfterBody
                | crate::hot::CardPlayStage::AfterEnchantment => Some(6),
                crate::hot::CardPlayStage::AfterImitation
                | crate::hot::CardPlayStage::AfterNormalHook => Some(8),
                crate::hot::CardPlayStage::StartBody => None,
            };
            if let Some(slot) = oblivion_slot {
                let mut malformed = canonical.clone();
                malformed.continuations[0]
                    .fields
                    .get_mut("latch")
                    .and_then(Value::as_array_mut)
                    .expect("projected latch is an array")[slot] = json!([[u64::MAX, 2]]);
                assert!(
                    HotBoundary::from_canonical(&malformed, &catalog).is_err(),
                    "stage {stage:?} accepted nonempty Oblivion latches"
                );
            }
        }
    }

    #[test]
    fn frozen_oblivion_latch_round_trips_recast_amount_and_rejects_forgery() {
        let (mut state, catalog) = pending_replay_state(PileId::Play, false, true);
        let owner_uid = state.monsters[0].uid;
        state.monsters_mut()[0]
            .powers
            .set(PowerId::Oblivion, SlotWire::Int, 6);
        state.monsters_mut()[0]
            .misery_debuff_order
            .push(crate::hot::MiseryToken::Oblivion);
        let mut record = state.frames.pop_top_card_play().unwrap();
        record.oblivion_latches = vec![(owner_uid, 3)];
        state.frames.push_card_play(&record).unwrap();

        let canonical = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        assert_eq!(
            canonical.continuations[0].fields["latch"][6],
            json!([[owner_uid, 3]])
        );
        assert_eq!(
            HotBoundary::from_canonical(&canonical, &catalog).unwrap(),
            state
        );

        for forged_latches in [
            json!([[owner_uid, 3], [owner_uid, 3]]),
            json!([[u64::MAX, 3]]),
            json!([[owner_uid, 0]]),
        ] {
            let mut forged = canonical.clone();
            forged.continuations[0]
                .fields
                .get_mut("latch")
                .and_then(Value::as_array_mut)
                .unwrap()[6] = forged_latches;
            assert!(HotBoundary::from_canonical(&forged, &catalog).is_err());
        }
    }

    #[test]
    fn nested_card_play_frames_round_trip_and_active_markers_fail_closed() {
        let (state, catalog) = nested_card_play_boundary_state();
        let canonical = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        assert_eq!(canonical.continuations.len(), 3);
        let expected_uids = state
            .frames
            .as_slice()
            .iter()
            .map(|frame| match *frame {
                Frame::CardPlay { record } => state.frames.card_play(record).unwrap().uid,
                _ => unreachable!(),
            })
            .collect::<Vec<_>>();
        assert_eq!(canonical.player["active_cards"], json!(expected_uids));
        assert_eq!(canonical.player["active_play"], json!([0, 1, 2]));
        assert!(canonical.player["pending"].is_array());
        assert!(canonical.continuations[2].fields["choice"].is_null());
        // This is a synthetic wire-inverse fixture: Defend does not create
        // these nested child bodies. With the selector correctly in Play,
        // its catalog requires the public replay root; structural roundtrip
        // must not confer executable authority on this originless stack.
        assert!(crate::engine::play::persisted_card_play_stack_is_exact(&state, &catalog).is_ok());
        assert!(crate::engine::admit(&canonical, &state, &catalog).is_err());
        assert_eq!(
            HotBoundary::from_canonical(&canonical, &catalog).unwrap(),
            state
        );

        let mut wrong_cards = expected_uids;
        wrong_cards.swap(0, 1);
        for (field, forged) in [
            ("active_cards", json!(wrong_cards)),
            ("active_play", json!([1, 0])),
        ] {
            let mut malformed = canonical.clone();
            malformed.player.insert(field.to_owned(), forged);
            assert!(HotBoundary::from_canonical(&malformed, &catalog).is_err());
        }
        let mut non_top_pending = canonical.clone();
        non_top_pending.continuations.swap(1, 2);
        assert!(HotBoundary::from_canonical(&non_top_pending, &catalog).is_err());

        let mut conflated_choice = canonical.clone();
        conflated_choice.continuations[2]
            .fields
            .insert("choice".to_owned(), json!(0));
        assert!(HotBoundary::from_canonical(&conflated_choice, &catalog).is_err());

        let mut pending_after_body = canonical.clone();
        pending_after_body.continuations[2]
            .fields
            .insert("stage".to_owned(), json!("after_body"));
        assert!(HotBoundary::from_canonical(&pending_after_body, &catalog).is_err());

        let mut ambiguous_lamp = canonical;
        ambiguous_lamp
            .player
            .insert("lamp_latched".to_owned(), Value::Bool(true));
        assert!(HotBoundary::from_canonical(&ambiguous_lamp, &catalog).is_err());
    }

    #[test]
    fn persisted_lamp_owner_requires_armed_state_and_a_resumable_stage() {
        let make_state = |stage, lamp_owner| {
            let relics: &[RelicId] = if lamp_owner {
                &[RelicId::RelicUnsettlingLamp]
            } else {
                &[]
            };
            let (mut state, catalog) =
                pending_replay_state_with_relics(PileId::Play, false, true, relics);
            let mut record = pending_record(&state).to_owned();
            record.pending_choice = false;
            record.selection_kind = None;
            record.selection_amount = 0;
            record.stage = stage;
            record.next_step = match stage {
                crate::hot::CardPlayStage::StartBody => 0,
                crate::hot::CardPlayStage::Body => 0,
                _ => 1,
            };
            record.latch_kind = match stage {
                crate::hot::CardPlayStage::StartBody => crate::hot::CardPlayLatchKind::Empty,
                crate::hot::CardPlayStage::Body
                | crate::hot::CardPlayStage::AfterBody
                | crate::hot::CardPlayStage::AfterEnchantment => crate::hot::CardPlayLatchKind::Raw,
                crate::hot::CardPlayStage::AfterImitation
                | crate::hot::CardPlayStage::AfterNormalHook => crate::hot::CardPlayLatchKind::Post,
            };
            record.lamp_owner = lamp_owner;
            state.frames = Frames::new();
            state.pending = None;
            state.fanouts.set_unsettling_lamp_available(true);
            state.frames.push_card_play(&record).unwrap();
            (state, catalog)
        };

        for stage in [
            crate::hot::CardPlayStage::Body,
            crate::hot::CardPlayStage::AfterImitation,
        ] {
            let (state, catalog) = make_state(stage, true);
            let canonical = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
            assert_eq!(canonical.player["lamp_latched"], json!(true));
            assert_eq!(
                HotBoundary::from_canonical(&canonical, &catalog).unwrap(),
                state
            );
            let mut unarmed = canonical;
            unarmed.player.insert("lamp".to_owned(), json!(false));
            assert!(HotBoundary::from_canonical(&unarmed, &catalog).is_err());
        }

        for stage in [
            crate::hot::CardPlayStage::StartBody,
            crate::hot::CardPlayStage::AfterNormalHook,
        ] {
            let (state, catalog) = make_state(stage, false);
            let mut impossible = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
            impossible
                .player
                .insert("lamp_latched".to_owned(), json!(true));
            assert!(HotBoundary::from_canonical(&impossible, &catalog).is_err());
        }
    }

    #[test]
    fn pending_card_play_spent_is_nonnegative_at_the_boundary() {
        for (manual, expected_spent) in [(false, 0), (true, 1)] {
            let source_pile = PileId::Play;
            let (state, catalog) = pending_replay_state(source_pile, manual, !manual);
            let canonical = HotBoundary::to_canonical(&state, &catalog);
            assert_eq!(canonical.continuations[0].fields["spent"], expected_spent);
            assert_eq!(
                HotBoundary::from_canonical(&canonical, &catalog).unwrap(),
                state
            );

            let mut negative = canonical;
            negative.continuations[0]
                .fields
                .insert("spent".to_owned(), json!(-1));
            let unchanged = negative.clone();
            assert!(HotBoundary::from_canonical(&negative, &catalog).is_err());
            assert_eq!(negative, unchanged);
        }

        let (state, catalog) = pending_replay_state(PileId::Play, true, false);
        let canonical = HotBoundary::to_canonical(&state, &catalog);
        for (field, value) in [
            ("plays", json!(0)),
            ("plays", json!(257)),
            ("plays", json!(u32::MAX)),
            (
                "play_index",
                canonical.continuations[0].fields["plays"].clone(),
            ),
            ("play_index", json!(u32::MAX)),
            ("spent", json!(i32::from(i16::MAX) + 1)),
        ] {
            let mut malformed = canonical.clone();
            malformed.continuations[0]
                .fields
                .insert(field.to_owned(), value);
            assert!(HotBoundary::from_canonical(&malformed, &catalog).is_err());
        }
        let mut impossible_force = canonical;
        impossible_force.continuations[0]
            .fields
            .insert("force_exhaust".to_owned(), json!(true));
        assert!(HotBoundary::from_canonical(&impossible_force, &catalog).is_err());
    }

