    /// The two counters #2481 slot 2 added share one packed word with the
    /// Waterfall/Test Subject/Queen/Merc payloads, so this pins three things
    /// at once: each round-trips losslessly, each is owner-gated on write, and
    /// a negative value is a named refusal rather than a wrapped `u32`.
    ///
    /// Zero-default elision is why the negative cases matter more than usual.
    /// Both fields default to 0, so an ordinary entry document omits them
    /// entirely and only a mid-turn root carries one — which is exactly the
    /// shape that let Bygone Effigy's counter go unread in slot 1.
    #[test]
    fn slot2_packed_monster_counters_round_trip_and_refuse_foreign_owners() {
        // The reader is passed in rather than selected by comparing `field`:
        // `boundary.rs` is below the D2 text-equality boundary, and the
        // hot-path contract test enforces that even in test code.
        /// Wire name, canonical field, a live value, and the typed reader.
        type CounterCase = (&'static str, &'static str, i32, fn(&HotMonster) -> i32);
        let readers: [CounterCase; 2] = [
            ("BYGONE_EFFIGY", "slow", 7, HotMonster::bygone_effigy_slow),
            (
                "SKULKING_COLONY",
                "shell_window",
                13,
                HotMonster::skulking_colony_shell_window,
            ),
        ];
        for (kind, field, value, read_counter) in readers {
            let mut document = minimal();
            document.monsters.push(BTreeMap::from([
                ("kind".to_owned(), json!(kind)),
                ("hp".to_owned(), json!(120)),
                ("max_hp".to_owned(), json!(120)),
                (field.to_owned(), json!(value)),
            ]));
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let hot = HotBoundary::from_canonical(&document, &catalog).unwrap();
            let monster = &hot.monsters[0];
            assert_eq!(
                read_counter(monster),
                value,
                "{kind}.{field} did not survive the load"
            );
            assert_eq!(
                HotBoundary::to_canonical(&hot, &catalog),
                document,
                "{kind}.{field} did not survive the projection"
            );

            // Negative is unrepresentable in either lifecycle: the Effigy
            // counter only increments and resets, and the Colony window only
            // accumulates already-capped non-negative loss.
            document.monsters[0].insert(field.to_owned(), json!(-1));
            assert!(
                matches!(
                    refuse(&document),
                    BoundaryRefusal::UnrepresentableValue { .. }
                ),
                "negative {kind}.{field} must refuse"
            );

            // The same field on a foreign owner is a refusal, not a silent
            // write into another tenant's half of the shared word.
            document.monsters[0].insert(field.to_owned(), json!(value));
            document.monsters[0].insert("kind".to_owned(), json!("TOADPOLE"));
            assert!(
                matches!(
                    refuse(&document),
                    BoundaryRefusal::UnrepresentableValue { .. }
                ),
                "{field} outside its owner must refuse"
            );
        }
    }

    /// A live value in either slot-2 counter must not read as a Waterfall
    /// buildup index.
    ///
    /// `pressure_buildup_idx()` masks the shared private word, so every tenant
    /// needs an explicit exclusion in admission's `waterfall_private_state`
    /// disjunct. The Queen, Gremlin Merc and Thieving Hopper each already had
    /// one; adding tenants without adding exclusions turned a legitimate fight
    /// into a spurious `waterfall private state` refusal — measured as one
    /// corpus row before this guard existed. Fail-closed, but still wrong.
    #[test]
    fn slot2_counters_do_not_read_as_waterfall_private_state() {
        for (kind, field) in [
            ("BYGONE_EFFIGY", "slow"),
            ("SKULKING_COLONY", "shell_window"),
        ] {
            let mut document = minimal();
            document.monsters.push(BTreeMap::from([
                ("kind".to_owned(), json!(kind)),
                ("hp".to_owned(), json!(120)),
                ("max_hp".to_owned(), json!(120)),
                (field.to_owned(), json!(4)),
            ]));
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let hot = HotBoundary::from_canonical(&document, &catalog).unwrap();
            let monster = &hot.monsters[0];
            // The masked read genuinely does alias — that is the hazard, and
            // pinning it here is what makes the admission exclusion load-bearing
            // rather than incidental.
            assert_eq!(
                monster.pressure_buildup_idx(),
                4,
                "{kind} aliases as expected"
            );
            assert!(
                !monster.is_about_to_blow(),
                "{kind} must not set the ABOUT latch"
            );
            assert!(
                !crate::engine::admission::admit(&document, &hot, &catalog)
                    .err()
                    .is_some_and(|refusal| refusal.contains(
                        crate::engine::admission::MissingCapability::ArgumentShape(
                            "waterfall private state"
                        )
                    )),
                "{kind} with a live {field} must not refuse as Waterfall private state"
            );
        }
    }

    #[test]
    fn waterfall_private_state_round_trips_without_default_elision_loss() {
        let mut document = minimal();
        document.monsters.push(BTreeMap::from([
            ("kind".to_owned(), json!("WATERFALL_GIANT")),
            ("hp".to_owned(), json!(999_999_999)),
            ("max_hp".to_owned(), json!(999_999_999)),
            ("loop_pos".to_owned(), json!(6)),
            ("steam_pressure".to_owned(), json!(35)),
            ("pressure_gun_damage".to_owned(), json!(28)),
            ("pressure_buildup_idx".to_owned(), json!(6)),
            ("steam_eruption_damage".to_owned(), json!(35)),
            ("is_about_to_blow".to_owned(), json!(true)),
        ]));

        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let hot = HotBoundary::from_canonical(&document, &catalog).unwrap();
        let monster = &hot.monsters[0];
        assert_eq!(monster.pressure_gun_damage, 28);
        assert_eq!(monster.pressure_buildup_idx(), 6);
        assert_eq!(monster.waterfall_steam_eruption_damage(), 35);
        assert!(monster.is_about_to_blow());
        assert_eq!(monster.powers.value(PowerId::SteamPressure), 35);
        assert_eq!(HotBoundary::to_canonical(&hot, &catalog), document);

        let mut independent = hot.clone();
        independent.monsters_mut()[0].set_is_about_to_blow(false);
        assert_eq!(independent.monsters[0].pressure_buildup_idx(), 6);
        assert!(!independent.monsters[0].is_about_to_blow());
        assert!(independent.monsters_mut()[0].set_pressure_buildup_idx(i32::MAX));
        assert_eq!(independent.monsters[0].pressure_buildup_idx(), i32::MAX);
        assert!(!independent.monsters[0].is_about_to_blow());

        document.monsters[0].insert("pressure_buildup_idx".to_owned(), json!(-1));
        assert!(matches!(
            refuse(&document),
            BoundaryRefusal::UnrepresentableValue { .. }
        ));
    }

    /// #3026: Scroll of Biting's repeated-CHEW latch is a Rust-only field. It
    /// round-trips on its owner, elides at its `false` default so earlier
    /// documents project unchanged, and refuses on any other monster.
    #[test]
    fn scroll_chew_repeated_latch_round_trips_on_its_owner_only() {
        let mut document = minimal();
        document.monsters.push(BTreeMap::from([
            ("kind".to_owned(), json!("SCROLL_OF_BITING")),
            ("hp".to_owned(), json!(33)),
            ("max_hp".to_owned(), json!(33)),
            ("loop_pos".to_owned(), json!(1)),
            ("scroll_chew_repeated".to_owned(), json!(true)),
        ]));
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let hot = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert!(hot.monsters[0].scroll_chew_repeated());
        assert!(hot.monsters[0].owner_latches_are_exact());
        assert_eq!(HotBoundary::to_canonical(&hot, &catalog), document);

        let mut unset = document.clone();
        unset.monsters[0].remove("scroll_chew_repeated");
        let catalog = HotBoundary::catalog_from_canonical(&unset).unwrap();
        let hot = HotBoundary::from_canonical(&unset, &catalog).unwrap();
        assert!(!hot.monsters[0].scroll_chew_repeated());
        assert_eq!(HotBoundary::to_canonical(&hot, &catalog), unset);

        let mut foreign = minimal();
        foreign.monsters.push(BTreeMap::from([
            ("kind".to_owned(), json!("TWIG_SLIME_M")),
            ("hp".to_owned(), json!(28)),
            ("max_hp".to_owned(), json!(28)),
            ("scroll_chew_repeated".to_owned(), json!(true)),
        ]));
        assert!(matches!(
            refuse(&foreign),
            BoundaryRefusal::UnrepresentableValue { .. }
        ));
    }

