    #[test]
    fn void_form_private_tuple_round_trips_and_orphans_refuse() {
        let mut document = minimal();
        document.player.insert("void_form".to_owned(), json!(2));
        document
            .player
            .insert("void_form_cards_played_this_turn".to_owned(), json!(7));
        append_singleton_after_card_played_row(&mut document, "void_form");
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let hot = HotBoundary::from_canonical(&document, &catalog).unwrap();
        assert!(crate::steps::regent_uncommon::void_form_private_state_is_exact(&hot));
        assert_eq!(HotBoundary::to_canonical(&hot, &catalog), document);
        let admission = crate::engine::admit(&document, &hot, &catalog).unwrap_err();
        assert!(admission.contains(crate::engine::MissingCapability::PlayerPhase(0)));
        assert!(!admission.contains(crate::engine::MissingCapability::Power(PowerId::VoidForm)));
        assert!(
            !admission.contains(crate::engine::MissingCapability::ArgumentShape(
                "void form private state"
            ))
        );

        for (field, value) in [
            ("void_form_cards_played_this_turn", json!(1)),
            ("end_turn_requested", json!(true)),
        ] {
            let mut orphan = minimal();
            orphan.player.insert(field.to_owned(), value);
            assert!(matches!(
                refuse(&orphan),
                BoundaryRefusal::UnrepresentableValue { .. }
            ));
        }

        let mut low_request = document;
        low_request
            .player
            .insert("end_turn_requested".to_owned(), json!(true));
        assert!(matches!(
            refuse(&low_request),
            BoundaryRefusal::UnrepresentableValue { .. }
        ));

        let mut deferred = minimal();
        deferred.player.insert("void_form".to_owned(), json!(2));
        deferred.player.insert(
            "void_form_cards_played_this_turn".to_owned(),
            json!(999_999_999),
        );
        deferred
            .player
            .insert("end_turn_requested".to_owned(), json!(true));
        append_singleton_after_card_played_row(&mut deferred, "void_form");
        let catalog = HotBoundary::catalog_from_canonical(&deferred).unwrap();
        let hot = HotBoundary::from_canonical(&deferred, &catalog).unwrap();
        assert_eq!(HotBoundary::to_canonical(&hot, &catalog), deferred);
        assert!(
            crate::engine::admit(&deferred, &hot, &catalog)
                .unwrap_err()
                .contains(crate::engine::MissingCapability::ArgumentShape(
                    "unresolved void form end-turn request"
                ))
        );
    }

