    #[test]
    fn phase_and_stampede_live_canonical_vocabularies_fail_closed() {
        let phase = CanonicalFrameV2 {
            frame_type: "PhaseFrame".to_owned(),
            fields: BTreeMap::from([
                ("tag".to_owned(), json!("phase")),
                ("phase".to_owned(), json!("auto_post")),
                ("subphase".to_owned(), json!("normal")),
                (
                    "snapshot".to_owned(),
                    json!([
                        ["power", "stampede"],
                        ["card", 7, "card", "HOWL_FROM_BEYOND"]
                    ]),
                ),
                ("cursor".to_owned(), json!(1)),
                ("terminal".to_owned(), json!("end_turn")),
                ("remaining".to_owned(), json!([])),
            ]),
        };
        assert_eq!(
            auto_post_phase_from_canonical(&phase).unwrap(),
            crate::hot::AutoPostPhaseRecord {
                cursor: 1,
                listeners: vec![
                    crate::hot::AutoPostListener::Stampede,
                    crate::hot::AutoPostListener::Howl { uid: 7 },
                ],
            }
        );
        for (field, value) in [
            ("tag", json!("card_play")),
            ("phase", json!("turn_end")),
            ("subphase", json!("early")),
            ("terminal", json!("none")),
            ("remaining", json!([1])),
            ("snapshot", json!([])),
            ("snapshot", json!(["power"])),
            ("snapshot", json!([["power", "unknown"]])),
            (
                "snapshot",
                json!([
                    ["card", 7, "card", "HOWL_FROM_BEYOND"],
                    ["power", "stampede"]
                ]),
            ),
            (
                "snapshot",
                json!([
                    ["power", "stampede"],
                    ["card", 7, "card", "HOWL_FROM_BEYOND"],
                    ["card", 7, "card", "HOWL_FROM_BEYOND"]
                ]),
            ),
            (
                "snapshot",
                json!([["card", -1, "card", "HOWL_FROM_BEYOND"]]),
            ),
            ("cursor", json!(-1)),
            ("cursor", json!(3)),
        ] {
            let mut malformed = phase.clone();
            malformed.fields.insert(field.to_owned(), value);
            assert!(
                auto_post_phase_from_canonical(&malformed).is_err(),
                "Phase mutation {field}"
            );
        }
        let mut extra = phase.clone();
        extra.fields.insert("extra".to_owned(), json!(0));
        assert!(auto_post_phase_from_canonical(&extra).is_err());

        let bombardment = CanonicalFrameV2 {
            frame_type: "PhaseFrame".to_owned(),
            fields: BTreeMap::from([
                ("tag".to_owned(), json!("phase")),
                ("phase".to_owned(), json!("auto_pre")),
                ("subphase".to_owned(), json!("early")),
                (
                    "snapshot".to_owned(),
                    json!([
                        ["card", 7, "card", "BOMBARDMENT"],
                        ["card", 19, "card", "BOMBARDMENT"]
                    ]),
                ),
                ("cursor".to_owned(), json!(1)),
                ("terminal".to_owned(), json!("ordinary_actions")),
                ("remaining".to_owned(), json!(["normal", "late"])),
            ]),
        };
        assert_eq!(
            auto_pre_bombardment_phase_from_canonical(&bombardment).unwrap(),
            crate::hot::AutoPreBombardmentPhaseRecord {
                cursor: 1,
                listeners: vec![7, 19],
            }
        );
        let mut phase_state = HotState::at_defaults();
        let record = phase_state
            .frames
            .push_auto_pre_bombardment_phase(&[7, 19])
            .unwrap();
        phase_state
            .frames
            .replace_top_auto_pre_bombardment_phase(&crate::hot::AutoPreBombardmentPhaseRecord {
                cursor: 1,
                listeners: vec![7, 19],
            })
            .unwrap();
        assert_eq!(
            frame_to_canonical(
                Frame::Phase { record },
                &phase_state,
                &CatalogBuilder::new().build(),
            )
            .unwrap(),
            bombardment,
            "the word-arena carrier emits the exact canonical early-phase vocabulary",
        );
        for (field, value) in [
            ("subphase", json!("normal")),
            ("snapshot", json!([])),
            ("snapshot", json!([["card", 0, "card", "BOMBARDMENT"]])),
            ("snapshot", json!([["card", 7, "card", "OTHER"]])),
            (
                "snapshot",
                json!([
                    ["card", 7, "card", "BOMBARDMENT"],
                    ["card", 7, "card", "BOMBARDMENT"]
                ]),
            ),
            ("cursor", json!(0)),
            ("cursor", json!(3)),
            ("remaining", json!(["late"])),
        ] {
            let mut malformed = bombardment.clone();
            malformed.fields.insert(field.to_owned(), value);
            assert!(
                auto_pre_bombardment_phase_from_canonical(&malformed).is_err(),
                "Bombardment phase mutation {field}"
            );
        }

        let live = CanonicalFrameV2 {
            frame_type: "LiveListenerFrame".to_owned(),
            fields: BTreeMap::from([
                ("tag".to_owned(), json!("live_listener")),
                ("work_key".to_owned(), json!("stampede_hand_attacks")),
                ("cursor".to_owned(), json!(1)),
                ("iterations".to_owned(), json!(2)),
                ("locals".to_owned(), json!([])),
            ]),
        };
        assert_eq!(
            stampede_live_from_canonical(&live).unwrap(),
            crate::hot::StampedeLiveRecord {
                cursor: 1,
                iterations: 2,
            }
        );
        for (field, value) in [
            ("tag", json!("phase")),
            ("work_key", json!("other")),
            ("locals", json!([0])),
            ("iterations", json!(0)),
            ("iterations", json!(-1)),
            ("iterations", json!(u64::from(u32::MAX) + 1)),
            ("cursor", json!(-1)),
            ("cursor", json!(3)),
        ] {
            let mut malformed = live.clone();
            malformed.fields.insert(field.to_owned(), value);
            assert!(
                stampede_live_from_canonical(&malformed).is_err(),
                "Live mutation {field}"
            );
        }
        let mut extra = live;
        extra.fields.insert("extra".to_owned(), json!(0));
        assert!(stampede_live_from_canonical(&extra).is_err());
    }

