    #[test]
    fn modeled_local_keywords_round_trip_and_other_keyword_shapes_refuse() {
        let mut document = minimal();
        let mut keyworded = card("STRIKE_IRONCLAD", 1);
        keyworded.local_keywords = vec!["Retain".to_owned()];
        keyworded.transient_keywords = vec!["Retain".to_owned()];
        document
            .piles
            .insert("hand".to_owned(), vec![keyworded.clone()]);
        assert_eq!(round_trip(&document), document);

        keyworded.local_keywords = vec!["Ethereal".to_owned()];
        document
            .piles
            .insert("hand".to_owned(), vec![keyworded.clone()]);
        assert_eq!(round_trip(&document), document);

        keyworded.local_keywords =
            vec!["Ethereal".to_owned(), "Retain".to_owned(), "Sly".to_owned()];
        document
            .piles
            .insert("hand".to_owned(), vec![keyworded.clone()]);
        assert_eq!(round_trip(&document), document);

        keyworded.local_keywords = vec!["Retain".to_owned(), "Sly".to_owned()];
        document.piles.insert("hand".to_owned(), vec![keyworded]);
        assert_eq!(round_trip(&document), document);

        let mut sly = card("STRIKE_IRONCLAD", 2);
        sly.local_keywords = vec!["Sly".to_owned()];
        document.piles.insert("hand".to_owned(), vec![sly]);
        assert_eq!(round_trip(&document), document);

        let mut reversed = card("STRIKE_IRONCLAD", 3);
        reversed.local_keywords = vec!["Sly".to_owned(), "Retain".to_owned()];
        document.piles.insert("hand".to_owned(), vec![reversed]);
        assert!(matches!(
            refuse(&document),
            BoundaryRefusal::UnrepresentableValue {
                entity: Entity::Card(3),
                field,
                ..
            } if matches!(field.as_str(), "local_keywords")
        ));

        let mut duplicated = card("STRIKE_IRONCLAD", 4);
        duplicated.transient_keywords = vec!["Retain".to_owned(), "Retain".to_owned()];
        document.piles.insert("hand".to_owned(), vec![duplicated]);
        assert!(matches!(
            refuse(&document),
            BoundaryRefusal::UnrepresentableValue {
                entity: Entity::Card(4),
                field,
                ..
            } if matches!(field.as_str(), "transient_keywords")
        ));

        let mut unplayable = card("STRIKE_IRONCLAD", 5);
        unplayable.local_keywords = vec!["Unplayable".to_owned()];
        document.piles.insert("hand".to_owned(), vec![unplayable]);
        assert!(matches!(
            refuse(&document),
            BoundaryRefusal::UnrepresentableValue {
                entity: Entity::Card(5),
                field,
                ..
            } if matches!(field.as_str(), "local_keywords")
        ));

        let mut unknown_tail = card("STRIKE_IRONCLAD", 6);
        unknown_tail.transient_keywords = vec!["Unplayable".to_owned()];
        document.piles.insert("hand".to_owned(), vec![unknown_tail]);
        assert!(matches!(
            refuse(&document),
            BoundaryRefusal::UnrepresentableValue {
                entity: Entity::Card(6),
                field,
                ..
            } if matches!(field.as_str(), "transient_keywords")
        ));

        let mut legacy = card("STRIKE_IRONCLAD", 0);
        legacy.uid = None;
        legacy.local_keywords = vec!["Sly".to_owned()];
        document.piles.insert("hand".to_owned(), vec![legacy]);
        assert_eq!(
            refuse(&document),
            BoundaryRefusal::UnsupportedField {
                entity: Entity::Document,
                field: "local_keywords".to_owned(),
            }
        );
    }

