    #[test]
    fn the_minimal_default_live_teammate_round_trips_exactly() {
        let solo = fixture();
        let solo_catalog = HotBoundary::catalog_from_canonical(&solo).unwrap();
        let solo_state = HotBoundary::from_canonical(&solo, &solo_catalog).unwrap();
        let solo_round_trip = HotBoundary::to_canonical(&solo_state, &solo_catalog);
        for field in [
            "multiplayer_allies",
            "multiplayer_player_order",
            "teammate_present",
        ] {
            assert!(!solo_round_trip.player.contains_key(field));
        }

        let mut document = fixture();
        add_minimal_multiplayer_party(&mut document);
        let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();

        let state = HotBoundary::from_canonical(&document, &catalog).unwrap();

        assert_eq!(state.multiplayer_ally_key, 1);
        assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);
    }

