    #[test]
    fn imitation_clone_records_require_power_payloads_and_reserved_uids() {
        let mut valid = fixture();
        add_minimal_multiplayer_party(&mut valid);
        valid
            .player
            .insert("imitation_learning".to_owned(), serde_json::json!([[0, 1]]));
        valid
            .player
            .insert("next_card_uid".to_owned(), serde_json::json!(11));
        valid.player.insert(
            "imitation_clone_records".to_owned(),
            serde_json::json!([[0, 8, 10, ["INFLAME", 0]]]),
        );
        let catalog = HotBoundary::catalog_from_canonical(&valid).unwrap();
        HotBoundary::from_canonical(&valid, &catalog).unwrap();

        let mut non_power = valid.clone();
        non_power.player.insert(
            "imitation_clone_records".to_owned(),
            serde_json::json!([[0, 8, 10, ["STRIKE_IRONCLAD", 0]]]),
        );
        let before = non_power.clone();
        let refusal = HotBoundary::from_canonical(&non_power, &catalog).unwrap_err();
        assert!(
            matches!(
            &refusal,
            BoundaryRefusal::UnrepresentableValue {
                entity: Entity::Player,
                field,
                detail,
            } if matches!(field.as_str(), "multiplayer_allies")
                && matches!(
                    detail.as_str(),
                    "ally-keyed powers disagree with the exact live Player roster"
                )
            ),
            "unexpected refusal: {refusal:?}"
        );
        assert_eq!(non_power, before, "failed load never mutates its document");

        let mut live_uid = valid;
        live_uid.player.insert(
            "imitation_clone_records".to_owned(),
            serde_json::json!([[0, 8, 8, ["INFLAME", 0]]]),
        );
        let refusal = HotBoundary::from_canonical(&live_uid, &catalog).unwrap_err();
        assert!(
            matches!(
                &refusal,
                BoundaryRefusal::UnrepresentableValue {
                    entity: Entity::Player,
                    field,
                    ..
                } if matches!(field.as_str(), "imitation_clone_records")
            ),
            "unexpected refusal: {refusal:?}"
        );
    }

