    #[test]
    fn core_field_power_name_collisions_are_the_four_closed_owner_scoped_cases() {
        for field in &PLAYER_FIELDS {
            let expected = match field.slot {
                PlayerSlot::TempStrength => Some(PowerId::TempStrength),
                PlayerSlot::ToricToughness => Some(PowerId::ToricToughness),
                _ => None,
            };
            assert_eq!(PowerId::from_str(field.name), expected, "{}", field.name);
        }
        // Player TemporaryStrengthPower projects its wrapper aggregate as the
        // core `State.temp_strength` field; monster negative temporary
        // Strength uses the same wire spelling inside each monster's power
        // bag. Entity-scoped boundary dispatch keeps the two distinct.
        // Python's Rend validator inventories `_curled` in its boolean
        // power-state vocabulary even though canonical `louse_curled` is the
        // Louse's private field, not a PowerModel slot. Core fields win the
        // boundary dispatch above; admission forbids PowerId::LouseCurled.
        // Knockdown is the second monster collision: its core field is the
        // closed distinct-instance array. A scalar PowerId slot is never a
        // second source of truth and fails admission before serialization.
        // `slow` is the third and has exactly the same shape: native keeps
        // SlowPower's Amount pinned at 1 and carries the interesting value in
        // the instance's `SlowAmount` DynamicVar, so Python projects the
        // private cards-played counter as the core `Monster.slow` field and
        // never as a power Amount. The core field wins the dispatch above, and
        // `PowerId::Slow` is absent from `IMPLEMENTED_POWERS`, so a document
        // that put Slow in a monster's power bag refuses rather than becoming
        // a rival source of truth.
        for field in &MONSTER_FIELDS {
            let expected = match field.slot {
                MonsterSlot::LouseCurled => Some(PowerId::LouseCurled),
                MonsterSlot::Knockdown => Some(PowerId::Knockdown),
                MonsterSlot::Slow => Some(PowerId::Slow),
                _ => None,
            };
            assert_eq!(PowerId::from_str(field.name), expected, "{}", field.name);
        }
    }

    #[test]
    fn defaults_agree_with_the_hot_constructors() {
        let state = HotState::at_defaults();
        for field in &PLAYER_FIELDS {
            let value = player_read(&state, None, field.slot);
            match field.default {
                FieldDefault::Required => {}
                other => assert!(
                    other.matches(&value),
                    "{} reads {value} but the table says {other:?}",
                    field.name
                ),
            }
        }
        let monster = HotMonster::new(MonsterKind::Toadpole, 7);
        for field in &MONSTER_FIELDS {
            let value = monster_read(&monster, field.slot);
            match field.default {
                FieldDefault::Required => {}
                other => assert!(
                    other.matches(&value),
                    "{} reads {value} but the table says {other:?}",
                    field.name
                ),
            }
        }
    }

    #[test]
    fn hello_world_turn_start_snapshot_round_trips_all_nonnegative_deltas() {
        fn hello_document(current: i64, snapshot: i64) -> CanonicalStateV2 {
            let mut document = fixture();
            document
                .player
                .insert("reward_card_pool".to_owned(), json!("Defect"));
            document
                .player
                .insert("hello_world".to_owned(), json!(current));
            if snapshot != 0 {
                document.player.insert(
                    "hello_world_amount_on_turn_start".to_owned(),
                    json!(snapshot),
                );
            }
            document.player.insert(
                "before_hand_draw_power_order".to_owned(),
                json!(["hello_world"]),
            );
            document.player.insert(
                "hello_world_generation_pool".to_owned(),
                Value::Array(
                    crate::content_tables::HELLO_WORLD_COMMON_POOL_V1101
                        .iter()
                        .map(|id| Value::from(id.as_str()))
                        .collect(),
                ),
            );
            document
        }

        for (current, snapshot) in [(2, 2), (2, 1), (3, 1), (i64::from(i32::MAX), 0)] {
            let document = hello_document(current, snapshot);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(
                state.hello_world_amount_on_turn_start(state.powers.value(PowerId::HelloWorld)),
                Some(snapshot as i32)
            );
            assert_eq!(HotBoundary::to_canonical(&state, &catalog), document);
        }

        for (current, snapshot) in [(2, 3), (1, -1), (1, i64::from(i32::MAX) + 1)] {
            let document = hello_document(current, snapshot);
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let refusal = HotBoundary::from_canonical(&document, &catalog).unwrap_err();
            assert!(
                matches!(
                    refusal,
                    BoundaryRefusal::UnrepresentableValue { ref field, .. }
                    if matches!(field.as_str(), "hello_world_amount_on_turn_start")
                ),
                "current={current} snapshot={snapshot}: {refusal:?}"
            );
        }
    }

